// ---- src/app/fleet/fleet.js ----
// --- 7. ĐỘI XE, RƠ-MOÓC & BÃI ---
let currentFleetSubTab = 'vehicles'; // 'vehicles' | 'trailers'
let rawFleetVehicles = [];
let rawFleetTrailers = [];
let fleetSortColumn = null;
let fleetSortDirection = 'asc';
let trailerSortColumn = null;
let trailerSortDirection = 'asc';

function switchFleetSubTab(tab) {
    currentFleetSubTab = tab === 'trailers' ? 'trailers' : 'vehicles';
    const btnVehicles = document.getElementById('fleet-tab-btn-vehicles');
    const btnTrailers = document.getElementById('fleet-tab-btn-trailers');
    const badgeVehicles = document.getElementById('fleet-badge-tractors-count');
    const badgeTrailers = document.getElementById('fleet-badge-trailers-count');
    const iconVehicles = btnVehicles ? btnVehicles.querySelector('i') : null;
    const iconTrailers = btnTrailers ? btnTrailers.querySelector('i') : null;
    const panelVehicles = document.getElementById('fleet-panel-vehicles');
    const panelTrailers = document.getElementById('fleet-panel-trailers');
    const btnCreateLabel = document.getElementById('btn-fleet-create-label');

    if (currentFleetSubTab === 'vehicles') {
        if (btnVehicles) {
            btnVehicles.className = 'fleet-subtab-btn flex-1 md:flex-initial h-10 px-4 rounded-xl text-xs md:text-sm font-bold font-heading flex items-center justify-center space-x-2 transition-all cursor-pointer border-2 border-teal-600 bg-teal-50/70 text-teal-900 shadow-2xs box-border';
        }
        if (badgeVehicles) {
            badgeVehicles.className = 'px-2 py-0.5 rounded-full text-[11px] font-black tabular-nums transition-all border bg-teal-100 text-teal-800 border-teal-200';
        }
        if (iconVehicles) {
            iconVehicles.className = 'ph-bold ph-truck text-base text-teal-600';
        }
        if (btnTrailers) {
            btnTrailers.className = 'fleet-subtab-btn flex-1 md:flex-initial h-10 px-4 rounded-xl text-xs md:text-sm font-bold font-heading flex items-center justify-center space-x-2 transition-all cursor-pointer border-2 border-transparent bg-transparent text-slate-600 hover:text-slate-900 hover:bg-slate-100 hover:border-slate-200 box-border';
        }
        if (badgeTrailers) {
            badgeTrailers.className = 'px-2 py-0.5 rounded-full text-[11px] font-black tabular-nums transition-all border bg-slate-100 text-slate-600 border-slate-200';
        }
        if (iconTrailers) {
            iconTrailers.className = 'ph-bold ph-arrows-horizontal text-base text-slate-500';
        }
        if (panelVehicles) panelVehicles.classList.remove('hidden');
        if (panelTrailers) panelTrailers.classList.add('hidden');
        if (btnCreateLabel) btnCreateLabel.innerText = 'Thêm Đầu Kéo';
        applyFleetFilters();
    } else {
        if (btnVehicles) {
            btnVehicles.className = 'fleet-subtab-btn flex-1 md:flex-initial h-10 px-4 rounded-xl text-xs md:text-sm font-bold font-heading flex items-center justify-center space-x-2 transition-all cursor-pointer border-2 border-transparent bg-transparent text-slate-600 hover:text-slate-900 hover:bg-slate-100 hover:border-slate-200 box-border';
        }
        if (badgeVehicles) {
            badgeVehicles.className = 'px-2 py-0.5 rounded-full text-[11px] font-black tabular-nums transition-all border bg-slate-100 text-slate-600 border-slate-200';
        }
        if (iconVehicles) {
            iconVehicles.className = 'ph-bold ph-truck text-base text-slate-500';
        }
        if (btnTrailers) {
            btnTrailers.className = 'fleet-subtab-btn flex-1 md:flex-initial h-10 px-4 rounded-xl text-xs md:text-sm font-bold font-heading flex items-center justify-center space-x-2 transition-all cursor-pointer border-2 border-indigo-600 bg-indigo-50/70 text-indigo-900 shadow-2xs box-border';
        }
        if (badgeTrailers) {
            badgeTrailers.className = 'px-2 py-0.5 rounded-full text-[11px] font-black tabular-nums transition-all border bg-indigo-100 text-indigo-800 border-indigo-200';
        }
        if (iconTrailers) {
            iconTrailers.className = 'ph-bold ph-arrows-horizontal text-base text-indigo-600';
        }
        if (panelVehicles) panelVehicles.classList.add('hidden');
        if (panelTrailers) panelTrailers.classList.remove('hidden');
        if (btnCreateLabel) btnCreateLabel.innerText = 'Thêm Rơ-Moóc';
        applyTrailerFilters();
    }
}

function filterFleetByWarning(warnType) {
    if (warnType === 'REG_WARNING') {
        const vehRegWarn = (rawFleetVehicles || []).filter(v => v.is_reg_warning || v.is_reg_expired).length;
        const trlRegWarn = (rawFleetTrailers || []).filter(t => t.is_reg_warning || t.is_reg_expired).length;
        if (trlRegWarn > 0 && vehRegWarn === 0) {
            switchFleetSubTab('trailers');
        } else if (currentFleetSubTab === 'trailers' && trlRegWarn > 0) {
            switchFleetSubTab('trailers');
        } else {
            switchFleetSubTab('vehicles');
        }
        const statusVeh = document.getElementById('filter-fleet-status');
        if (statusVeh) statusVeh.value = 'REG_WARNING';
        const statusTrl = document.getElementById('filter-trailer-status');
        if (statusTrl) statusTrl.value = 'REG_WARNING';
        applyFleetFilters();
        applyTrailerFilters();
    } else if (warnType === 'MAINT_WARNING') {
        switchFleetSubTab('vehicles');
        const statusVeh = document.getElementById('filter-fleet-status');
        if (statusVeh) statusVeh.value = 'MAINT_WARNING';
        applyFleetFilters();
    }
}

async function openCreateFleetItemModal() {
    if (currentFleetSubTab === 'trailers') {
        if (typeof openMasterDataModalQuick === 'function') {
            await openMasterDataModalQuick('trailers');
        }
    } else {
        if (typeof openMasterDataModalQuick === 'function') {
            await openMasterDataModalQuick('vehicles');
        }
    }
}

async function editFleetVehicle(id) {
    if (typeof openEditMasterDataModal === 'function') {
        currentMasterDataTab = 'vehicles';
        await openEditMasterDataModal(id);
    }
}

async function editFleetTrailer(id) {
    if (typeof openEditMasterDataModal === 'function') {
        currentMasterDataTab = 'trailers';
        await openEditMasterDataModal(id);
    }
}

function exportCurrentFleetList() {
    const isTrailer = currentFleetSubTab === 'trailers';
    const list = isTrailer ? (rawFleetTrailers || []) : (rawFleetVehicles || []);
    if (!list || !list.length) {
        if (typeof showToast === 'function') {
            showToast('warning', 'Không có dữ liệu phương tiện để xuất.', 'Thông Báo');
        }
        return;
    }

    let csvContent = '\uFEFF';
    if (isTrailer) {
        csvContent += 'STT,Biển Số Moóc,Quy Cách / Loại Moóc,Hãng Sản Xuất,Tải Trọng (kg),Hạn Đăng Kiểm,Trạng Thái\n';
        list.forEach((t, i) => {
            const row = [
                i + 1,
                `"${(t.plate || '').replace(/"/g, '""')}"`,
                `"${(t.type || '').replace(/"/g, '""')}"`,
                `"${(t.brand || '').replace(/"/g, '""')}"`,
                `"${(t.payload_display || '').replace(/"/g, '""')}"`,
                `"${(t.reg_expiry || '').replace(/"/g, '""')}"`,
                `"${(t.status || '').replace(/"/g, '""')}"`
            ];
            csvContent += row.join(',') + '\n';
        });
    } else {
        csvContent += 'STT,Biển Số Xe,Loại Xe,Hình Thức Sở Hữu,Tài Xế Mặc Định,Hạn Đăng Kiểm,Lịch Bảo Trì,Trạng Thái\n';
        list.forEach((v, i) => {
            const row = [
                i + 1,
                `"${(v.plate || '').replace(/"/g, '""')}"`,
                `"${(v.type || '').replace(/"/g, '""')}"`,
                `"${(v.ownership_type || '').replace(/"/g, '""')}"`,
                `"${(v.driver || '').replace(/"/g, '""')}"`,
                `"${(v.reg_expiry || '').replace(/"/g, '""')}"`,
                `"${(v.maint_date || '').replace(/"/g, '""')}"`,
                `"${(v.status || '').replace(/"/g, '""')}"`
            ];
            csvContent += row.join(',') + '\n';
        });
    }

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    const url = URL.createObjectURL(blob);
    link.setAttribute('href', url);
    link.setAttribute('download', `${isTrailer ? 'Danh_Sach_Ro_Mooc' : 'Danh_Sach_Dau_Keo'}_${new Date().toISOString().slice(0, 10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    if (typeof showToast === 'function') {
        showToast('success', `Đã xuất danh sách ${isTrailer ? 'Rơ-Moóc' : 'Đầu Kéo'} thành công!`, 'Thành Công');
    }
}

// --- QUẢN LÝ ĐẦU KÉO & XE TẢI ---
function populateFleetFilterDropdowns(vehicles) {
    if (!vehicles || !Array.isArray(vehicles)) return;
    const typeSelect = document.getElementById('filter-fleet-type');
    if (typeSelect) {
        const curVal = typeSelect.value;
        const types = [...new Set(vehicles.map(v => (v.type || '').trim()).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'vi'));
        typeSelect.innerHTML = '<option value="">-- Tất cả Loại phương tiện --</option>' + 
            types.map(t => `<option value="${escapeHtml(t)}">${escapeHtml(t)}</option>`).join('');
        if (types.includes(curVal)) typeSelect.value = curVal;
    }
}

function clearFleetSearch() {
    const input = document.getElementById('filter-fleet-search');
    if (input) input.value = '';
    const clearBtn = document.getElementById('btn-clear-fleet-search');
    if (clearBtn) clearBtn.classList.add('hidden');
    applyFleetFilters();
}

function resetFleetFilters() {
    const type = document.getElementById('filter-fleet-type');
    if (type) type.value = '';
    const status = document.getElementById('filter-fleet-status');
    if (status) status.value = '';
    const search = document.getElementById('filter-fleet-search');
    if (search) search.value = '';
    const clearBtn = document.getElementById('btn-clear-fleet-search');
    if (clearBtn) clearBtn.classList.add('hidden');

    fleetSortColumn = null;
    fleetSortDirection = 'asc';
    applyFleetFilters();
}

function toggleFleetSort(col) {
    if (fleetSortColumn === col) {
        fleetSortDirection = fleetSortDirection === 'asc' ? 'desc' : 'asc';
    } else {
        fleetSortColumn = col;
        fleetSortDirection = 'asc';
    }
    applyFleetFilters();
}

function applyFleetFilters() {
    if (!rawFleetVehicles || !Array.isArray(rawFleetVehicles)) return;

    const filterType = document.getElementById('filter-fleet-type')?.value?.trim().toLowerCase() || '';
    const filterStatus = document.getElementById('filter-fleet-status')?.value?.trim() || '';
    const filterSearch = document.getElementById('filter-fleet-search')?.value?.trim().toLowerCase() || '';

    const clearBtn = document.getElementById('btn-clear-fleet-search');
    if (clearBtn) {
        if (filterSearch) clearBtn.classList.remove('hidden');
        else clearBtn.classList.add('hidden');
    }

    let list = rawFleetVehicles.filter(v => {
        if (filterType && (v.type || '').toLowerCase() !== filterType) return false;

        if (filterStatus) {
            if (filterStatus === 'REG_WARNING') {
                if (!v.is_reg_warning && !v.is_reg_expired) return false;
            } else if (filterStatus === 'MAINT_WARNING') {
                if (!v.is_maint_warning) return false;
            } else if (v.status !== filterStatus) {
                return false;
            }
        }

        if (filterSearch) {
            const combinedText = [
                v.plate,
                v.type,
                v.driver,
                v.reg_expiry,
                v.maint_date,
                v.status
            ].filter(Boolean).join(' ').toLowerCase();

            if (!combinedText.includes(filterSearch)) return false;
        }

        return true;
    });

    // Cập nhật số đếm
    const filteredCountEl = document.getElementById('fleet-filtered-count');
    if (filteredCountEl) filteredCountEl.innerText = list.length;
    const totalCountEl = document.getElementById('fleet-total-count');
    if (totalCountEl) totalCountEl.innerText = rawFleetVehicles.length;

    // Sắp xếp
    if (fleetSortColumn) {
        list.sort((a, b) => {
            let valA = (a[fleetSortColumn] || '').toString();
            let valB = (b[fleetSortColumn] || '').toString();
            const cmp = valA.localeCompare(valB, 'vi');
            return fleetSortDirection === 'asc' ? cmp : -cmp;
        });
    }

    // Cập nhật icon thead
    const sortCols = ['plate', 'type', 'driver', 'reg_expiry', 'maint_date', 'status'];
    sortCols.forEach(col => {
        const iconEl = document.getElementById(`sort-icon-fleet-${col}`);
        if (iconEl) {
            if (fleetSortColumn === col) {
                iconEl.className = fleetSortDirection === 'asc' 
                    ? 'ph-bold ph-arrow-up text-teal-600 text-xs' 
                    : 'ph-bold ph-arrow-down text-teal-600 text-xs';
            } else {
                iconEl.className = 'ph-bold ph-arrows-down-up text-slate-400 text-xs';
            }
        }
    });

    renderFleetTable(list);
}

function renderFleetTable(vehicles) {
    const tbody = document.getElementById('fleet-tbody');
    if (!tbody) return;
    tbody.innerHTML = '';

    if (!vehicles || vehicles.length === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="8" class="text-center py-10 text-slate-400">
                    <div class="flex flex-col items-center justify-center">
                        <i class="ph ph-truck text-3xl mb-2 text-slate-300"></i>
                        <p class="font-medium text-sm text-slate-500">Không tìm thấy phương tiện nào phù hợp với bộ lọc</p>
                        <p class="text-xs text-slate-400 mt-1">Thử đổi điều kiện lọc hoặc bấm "Đặt lại"</p>
                        <button onclick="resetFleetFilters()" class="mt-2.5 px-3 py-1 bg-teal-50 text-teal-700 hover:bg-teal-100 rounded-lg text-xs font-bold transition-colors cursor-pointer">
                            Đặt lại bộ lọc
                        </button>
                    </div>
                </td>
            </tr>
        `;
        return;
    }

    vehicles.forEach((v, idx) => {
        let statusCls = 'text-emerald-700 font-bold';
        if (v.is_reg_expired) statusCls = 'text-rose-700 font-black';
        else if (v.is_reg_warning || v.is_maint_warning || v.is_ins_warning) statusCls = 'text-amber-700 font-bold';

        let regBadge = '';
        if (v.is_reg_expired) {
            regBadge = `<span class="text-[11px] font-bold text-rose-700 mt-0.5 inline-flex items-center gap-1"><i class="ph-bold ph-warning-circle"></i>Hết hạn (${Math.abs(v.reg_days_left)}N)</span>`;
        } else if (v.is_reg_warning) {
            regBadge = `<span class="text-[11px] font-bold text-amber-700 mt-0.5 inline-flex items-center gap-1"><i class="ph-bold ph-clock"></i>Còn ${v.reg_days_left} ngày</span>`;
        } else if (v.reg_days_left !== null && v.reg_days_left !== undefined) {
            regBadge = `<span class="text-[11px] text-emerald-700 font-bold mt-0.5 block">Hợp lệ (${v.reg_days_left}N)</span>`;
        }

        let maintBadge = '';
        if (v.is_maint_warning) {
            maintBadge = `<span class="text-[11px] font-bold text-amber-700 mt-0.5 inline-flex items-center gap-1"><i class="ph-bold ph-wrench"></i>Đến hạn (${v.maint_days_left}N)</span>`;
        } else if (v.maint_days_left !== null && v.maint_days_left !== undefined) {
            maintBadge = `<span class="text-[11px] text-slate-500 font-medium mt-0.5 block">Còn ${v.maint_days_left}N</span>`;
        }

        const tr = document.createElement('tr');
        tr.className = 'hover:bg-slate-50 transition-colors border-b border-slate-200/80';
        tr.innerHTML = `
            <td class="p-4 text-center font-mono text-xs font-bold text-slate-500 tabular-nums select-none border-r border-slate-200/70 w-12">
                ${idx + 1}
            </td>
            <td class="p-4 font-black text-slate-900 font-heading text-sm">${escapeHtml(v.plate)}</td>
            <td class="p-4 font-medium text-slate-700 text-sm">
                <div>${escapeHtml(v.type)}</div>
                <span class="text-[10.5px] font-bold ${v.ownership_code === 'OWNED' ? 'text-teal-700' : 'text-amber-700'}">${escapeHtml(v.ownership_type)}</span>
            </td>
            <td class="p-4 font-bold text-slate-800 text-sm">${escapeHtml(v.driver)}</td>
            <td class="p-4 text-sm font-medium">
                <div class="${v.is_reg_expired ? 'text-rose-700 font-black' : v.is_reg_warning ? 'text-amber-700 font-bold' : 'text-slate-700'}">${escapeHtml(v.reg_expiry)}</div>
                ${regBadge}
            </td>
            <td class="p-4 text-sm font-medium">
                <div class="${v.is_maint_warning ? 'text-amber-600 font-bold' : 'text-slate-600'}">${escapeHtml(v.maint_date)}</div>
                ${maintBadge}
            </td>
            <td class="p-4">
                <span class="text-xs font-bold uppercase tracking-wider font-heading ${statusCls}">${escapeHtml(v.status)}</span>
            </td>
            <td class="p-4 text-center">
                <div class="flex items-center justify-center space-x-1">
                    <button type="button" onclick="editFleetVehicle(${v.id})" class="p-1.5 text-slate-500 hover:text-teal-700 hover:bg-teal-50 rounded-lg transition-colors cursor-pointer" title="Chỉnh sửa thông tin phương tiện">
                        <i class="ph-bold ph-pencil-simple text-sm"></i>
                    </button>
                </div>
            </td>
        `;
        tbody.appendChild(tr);
    });

    if (window.BimTableFooter && Array.isArray(vehicles)) {
        const activeVehicles = vehicles.filter(v => v.status === 'Hoạt động' || v.status === 'ACTIVE').length;
        const maintVehicles = vehicles.filter(v => v.status === 'Bảo trì' || v.status === 'MAINTENANCE').length;
        window.BimTableFooter.render('fleet-vehicles-table', {
            cells: [
                { text: 'TỔNG', align: 'center', class: 'font-black text-slate-900 font-heading' },
                { html: `<span class="text-teal-800 font-extrabold">${vehicles.length}</span> phương tiện | Hoạt động: <span class="text-emerald-700 font-bold">${activeVehicles}</span> | Đang bảo dưỡng / dừng: <span class="text-amber-700 font-bold">${maintVehicles}</span>`, colspan: 6, class: 'text-slate-700' },
                { text: '', align: 'center' }
            ]
        });
    }
}

// --- QUẢN LÝ RƠ-MOÓC CONTAINER ---
function populateTrailerFilterDropdowns(trailers) {
    if (!trailers || !Array.isArray(trailers)) return;
    const typeSelect = document.getElementById('filter-trailer-type');
    if (typeSelect) {
        const curVal = typeSelect.value;
        const types = [...new Set(trailers.map(t => (t.type || '').trim()).filter(Boolean))].sort((a, b) => a.localeCompare(b, 'vi'));
        typeSelect.innerHTML = '<option value="">-- Tất cả Loại Rơ-moóc --</option>' + 
            types.map(t => `<option value="${escapeHtml(t)}">${escapeHtml(t)}</option>`).join('');
        if (types.includes(curVal)) typeSelect.value = curVal;
    }
}

function clearTrailerSearch() {
    const input = document.getElementById('filter-trailer-search');
    if (input) input.value = '';
    const clearBtn = document.getElementById('btn-clear-trailer-search');
    if (clearBtn) clearBtn.classList.add('hidden');
    applyTrailerFilters();
}

function resetTrailerFilters() {
    const type = document.getElementById('filter-trailer-type');
    if (type) type.value = '';
    const status = document.getElementById('filter-trailer-status');
    if (status) status.value = '';
    const search = document.getElementById('filter-trailer-search');
    if (search) search.value = '';
    const clearBtn = document.getElementById('btn-clear-trailer-search');
    if (clearBtn) clearBtn.classList.add('hidden');

    trailerSortColumn = null;
    trailerSortDirection = 'asc';
    applyTrailerFilters();
}

function toggleTrailerSort(col) {
    if (trailerSortColumn === col) {
        trailerSortDirection = trailerSortDirection === 'asc' ? 'desc' : 'asc';
    } else {
        trailerSortColumn = col;
        trailerSortDirection = 'asc';
    }
    applyTrailerFilters();
}

function applyTrailerFilters() {
    if (!rawFleetTrailers || !Array.isArray(rawFleetTrailers)) return;

    const filterType = document.getElementById('filter-trailer-type')?.value?.trim().toLowerCase() || '';
    const filterStatus = document.getElementById('filter-trailer-status')?.value?.trim() || '';
    const filterSearch = document.getElementById('filter-trailer-search')?.value?.trim().toLowerCase() || '';

    const clearBtn = document.getElementById('btn-clear-trailer-search');
    if (clearBtn) {
        if (filterSearch) clearBtn.classList.remove('hidden');
        else clearBtn.classList.add('hidden');
    }

    let list = rawFleetTrailers.filter(t => {
        if (filterType && (t.type || '').toLowerCase() !== filterType) return false;

        if (filterStatus) {
            if (filterStatus === 'REG_WARNING') {
                if (!t.is_reg_warning && !t.is_reg_expired) return false;
            } else if (t.status_raw !== filterStatus && t.status !== filterStatus) {
                return false;
            }
        }

        if (filterSearch) {
            const combinedText = [
                t.plate,
                t.type,
                t.brand,
                t.payload_display,
                t.reg_expiry,
                t.status
            ].filter(Boolean).join(' ').toLowerCase();

            if (!combinedText.includes(filterSearch)) return false;
        }

        return true;
    });

    // Cập nhật số đếm
    const filteredCountEl = document.getElementById('trailer-filtered-count');
    if (filteredCountEl) filteredCountEl.innerText = list.length;
    const totalCountEl = document.getElementById('trailer-total-count');
    if (totalCountEl) totalCountEl.innerText = rawFleetTrailers.length;

    // Sắp xếp
    if (trailerSortColumn) {
        list.sort((a, b) => {
            let valA = '';
            let valB = '';
            if (trailerSortColumn === 'payload') {
                valA = a.payload_capacity_kg || 0;
                valB = b.payload_capacity_kg || 0;
                return trailerSortDirection === 'asc' ? valA - valB : valB - valA;
            } else {
                valA = (a[trailerSortColumn] || '').toString();
                valB = (b[trailerSortColumn] || '').toString();
                const cmp = valA.localeCompare(valB, 'vi');
                return trailerSortDirection === 'asc' ? cmp : -cmp;
            }
        });
    }

    // Cập nhật icon thead
    const sortCols = ['plate', 'type', 'brand', 'payload', 'reg_expiry', 'status'];
    sortCols.forEach(col => {
        const iconEl = document.getElementById(`sort-icon-trailer-${col}`);
        if (iconEl) {
            if (trailerSortColumn === col) {
                iconEl.className = trailerSortDirection === 'asc' 
                    ? 'ph-bold ph-arrow-up text-indigo-600 text-xs' 
                    : 'ph-bold ph-arrow-down text-indigo-600 text-xs';
            } else {
                iconEl.className = 'ph-bold ph-arrows-down-up text-slate-400 text-xs';
            }
        }
    });

    renderTrailerTable(list);
}

function renderTrailerTable(trailers) {
    const tbody = document.getElementById('trailer-tbody');
    if (!tbody) return;
    tbody.innerHTML = '';

    if (!trailers || trailers.length === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="8" class="text-center py-10 text-slate-400">
                    <div class="flex flex-col items-center justify-center">
                        <i class="ph ph-arrows-horizontal text-3xl mb-2 text-slate-300"></i>
                        <p class="font-medium text-sm text-slate-500">Không tìm thấy rơ-moóc nào phù hợp với bộ lọc</p>
                        <p class="text-xs text-slate-400 mt-1">Thử đổi điều kiện lọc hoặc bấm "Đặt lại"</p>
                        <button onclick="resetTrailerFilters()" class="mt-2.5 px-3 py-1 bg-indigo-50 text-indigo-700 hover:bg-indigo-100 rounded-lg text-xs font-bold transition-colors cursor-pointer">
                            Đặt lại bộ lọc
                        </button>
                    </div>
                </td>
            </tr>
        `;
        return;
    }

    trailers.forEach((t, idx) => {
        let statusCls = 'text-slate-700 font-bold';
        if (t.status_raw === 'ACTIVE' || (t.status && t.status.includes('Đang kéo'))) {
            statusCls = 'text-emerald-700 font-bold';
        } else if (t.status_raw === 'IDLE' || (t.status && t.status.includes('Nằm bãi'))) {
            statusCls = 'text-teal-700 font-bold';
        } else if (t.status_raw === 'MAINTENANCE' || (t.status && (t.status.includes('Bảo trì') || t.status.includes('Hư hỏng')))) {
            statusCls = 'text-amber-700 font-bold';
        }

        let regBadge = '';
        if (t.is_reg_expired) {
            regBadge = `<span class="text-[11px] font-bold text-rose-700 mt-0.5 inline-flex items-center gap-1"><i class="ph-bold ph-warning-circle"></i>Hết hạn (${Math.abs(t.reg_days_left)}N)</span>`;
        } else if (t.is_reg_warning) {
            regBadge = `<span class="text-[11px] font-bold text-amber-700 mt-0.5 inline-flex items-center gap-1"><i class="ph-bold ph-clock"></i>Còn ${t.reg_days_left} ngày</span>`;
        } else if (t.reg_days_left !== null && t.reg_days_left !== undefined) {
            regBadge = `<span class="text-[11px] text-emerald-700 font-bold mt-0.5 block">Hợp lệ (${t.reg_days_left}N)</span>`;
        }

        const tr = document.createElement('tr');
        tr.className = 'hover:bg-slate-50 transition-colors border-b border-slate-200/80';
        tr.innerHTML = `
            <td class="p-4 text-center font-mono text-xs font-bold text-slate-500 tabular-nums select-none border-r border-slate-200/70 w-12">
                ${idx + 1}
            </td>
            <td class="p-4 font-black text-slate-900 font-mono text-sm">${escapeHtml(t.plate)}</td>
            <td class="p-4 font-medium text-slate-800 text-sm">
                <div>${escapeHtml(t.type || 'Moóc Container')}</div>
            </td>
            <td class="p-4 font-semibold text-slate-700 text-sm">${escapeHtml(t.brand || '—')}</td>
            <td class="p-4 font-mono font-bold text-slate-900 text-right text-sm tabular-nums">
                ${escapeHtml(t.payload_display || '—')} <span class="text-[11px] font-normal text-slate-500">kg</span>
            </td>
            <td class="p-4 text-sm font-medium">
                <div class="${t.is_reg_expired ? 'text-rose-700 font-black' : t.is_reg_warning ? 'text-amber-700 font-bold' : 'text-slate-700 font-mono font-bold'}">${escapeHtml(t.reg_expiry)}</div>
                ${regBadge}
            </td>
            <td class="p-4">
                <span class="text-xs font-bold uppercase tracking-wider font-heading ${statusCls}">${escapeHtml(t.status || '—')}</span>
            </td>
            <td class="p-4 text-center">
                <div class="flex items-center justify-center space-x-1">
                    <button type="button" onclick="editFleetTrailer(${t.id})" class="p-1.5 text-slate-500 hover:text-indigo-700 hover:bg-indigo-50 rounded-lg transition-colors cursor-pointer" title="Chỉnh sửa thông tin rơ-moóc">
                        <i class="ph-bold ph-pencil-simple text-sm"></i>
                    </button>
                </div>
            </td>
        `;
        tbody.appendChild(tr);
    });

    if (window.BimTableFooter && Array.isArray(trailers)) {
        const activeTrailers = trailers.filter(t => t.status_raw === 'ACTIVE' || (t.status || '').includes('Đang kéo')).length;
        const idleTrailers = trailers.filter(t => t.status_raw === 'IDLE' || (t.status || '').includes('Nằm bãi')).length;
        const maintTrailers = trailers.filter(t => t.status_raw === 'MAINTENANCE' || (t.status || '').includes('Bảo trì')).length;
        window.BimTableFooter.render('fleet-trailers-table', {
            cells: [
                { text: 'TỔNG', align: 'center', class: 'font-black text-slate-900 font-heading' },
                { html: `<span class="text-indigo-800 font-extrabold">${trailers.length}</span> rơ-moóc | Nằm bãi: <span class="text-teal-700 font-bold">${idleTrailers}</span> | Đang kéo: <span class="text-emerald-700 font-bold">${activeTrailers}</span> | Bảo trì: <span class="text-amber-700 font-bold">${maintTrailers}</span>`, colspan: 6, class: 'text-slate-700' },
                { text: '', align: 'center' }
            ]
        });
    }
}

async function loadFleetData() {
    try {
        const res = await fetchWithAuth('/api/fleet/');
        if (!res.ok) throw new Error('Lỗi tải đội xe');
        const data = await res.json();

        const statTractorsEl = document.getElementById('fleet-stat-tractors');
        if (statTractorsEl) statTractorsEl.innerText = data.total_tractors || 0;
        const statTrailersEl = document.getElementById('fleet-stat-trailers');
        if (statTrailersEl) statTrailersEl.innerText = data.total_trailers || 0;
        const statRegEl = document.getElementById('fleet-stat-reg');
        if (statRegEl) statRegEl.innerText = data.reg_warning_count || 0;
        const statMaintEl = document.getElementById('fleet-stat-maint');
        if (statMaintEl) statMaintEl.innerText = data.maint_warning_count || 0;

        // Cập nhật 2 dòng số liệu nghiệp vụ 5 Thẻ Đội Xe
        const setTxt = (id, val) => { const el = document.getElementById(id); if (el && val) el.innerText = val; };
        setTxt('fleet-stat-availability', data.card_availability?.rate || '100%');
        setTxt('fleet-card-tractors-line1', data.card_tractors?.line_1);
        setTxt('fleet-card-tractors-line2', data.card_tractors?.line_2);
        setTxt('fleet-card-trailers-line1', data.card_trailers?.line_1);
        setTxt('fleet-card-trailers-line2', data.card_trailers?.line_2);
        setTxt('fleet-card-avail-line1', data.card_availability?.line_1);
        setTxt('fleet-card-avail-line2', data.card_availability?.line_2);
        setTxt('fleet-card-reg-line1', data.card_reg?.line_1);
        setTxt('fleet-card-reg-line2', data.card_reg?.line_2);
        setTxt('fleet-card-maint-line1', data.card_maint?.line_1);
        setTxt('fleet-card-maint-line2', data.card_maint?.line_2);

        const badgeTractorsEl = document.getElementById('fleet-badge-tractors-count');
        if (badgeTractorsEl) badgeTractorsEl.innerText = data.total_tractors || 0;
        const badgeTrailersEl = document.getElementById('fleet-badge-trailers-count');
        if (badgeTrailersEl) badgeTrailersEl.innerText = data.total_trailers || 0;

        rawFleetVehicles = data.vehicles || [];
        rawFleetTrailers = data.trailers || [];
        populateFleetFilterDropdowns(rawFleetVehicles);
        populateTrailerFilterDropdowns(rawFleetTrailers);
        applyFleetFilters();
        applyTrailerFilters();
    } catch (err) {
        console.error('Error loading fleet data:', err);
    }
}

// ---- src/app/hr/employees.js ----
// --- 6. PHÂN HỆ QUẢN TRỊ NHÂN SỰ & HYBRID PAYROLL ---
let currentHRSubTab = 'directory';
let rawEmployeesList = [];
let rawContractsList = [];
let rawPayrollPeriodsList = [];
let currentPayrollPeriodDetail = null;
let currentPayrollSlipsList = [];

async function loadHRData() {
    const activeSubTab = currentHRSubTab || 'directory';
    await loadEmployeesData();
    if (activeSubTab !== 'directory') {
        switchHRSubTab(activeSubTab);
    }
}

function switchHRSubTab(tabKey) {
    currentHRSubTab = tabKey;
    const tabs = ['directory', 'contracts', 'attendance', 'payroll', 'policies'];
    
    tabs.forEach(t => {
        const btn = document.getElementById(`hr-tab-${t}-btn`);
        const panel = document.getElementById(`hr-panel-${t}`);
        if (btn) {
            if (t === tabKey) {
                btn.className = 'hr-tab-btn active h-10 px-3.5 rounded-xl text-xs md:text-sm font-bold font-heading flex items-center justify-center space-x-1.5 transition-all cursor-pointer border-2 border-teal-600 bg-teal-50/70 text-teal-900 shadow-2xs box-border whitespace-nowrap';
            } else {
                btn.className = 'hr-tab-btn h-10 px-3.5 rounded-xl text-xs md:text-sm font-bold font-heading flex items-center justify-center space-x-1.5 transition-all cursor-pointer border-2 border-transparent bg-transparent text-slate-600 hover:text-slate-900 hover:bg-slate-100 hover:border-slate-200 box-border whitespace-nowrap';
            }
        }
        if (panel) {
            if (t === tabKey) panel.classList.remove('hidden');
            else panel.classList.add('hidden');
        }
    });

    const createEmpBtn = document.getElementById('btn-create-employee');
    const createContractBtn = document.getElementById('btn-create-contract');
    const autoAttendanceBtn = document.getElementById('btn-auto-attendance');
    const createPeriodBtn = document.getElementById('btn-create-period');

    if (createEmpBtn) createEmpBtn.classList.toggle('hidden', tabKey !== 'directory');
    const empTemplateBtn = document.getElementById('btn-employee-template');
    const empImportBtn = document.getElementById('btn-employee-import');
    const empExportBtn = document.getElementById('btn-employee-export');
    if (empTemplateBtn) empTemplateBtn.classList.toggle('hidden', tabKey !== 'directory');
    if (empImportBtn) empImportBtn.classList.toggle('hidden', tabKey !== 'directory');
    if (empExportBtn) empExportBtn.classList.toggle('hidden', tabKey !== 'directory');
    if (createContractBtn) createContractBtn.classList.toggle('hidden', tabKey !== 'contracts');
    if (autoAttendanceBtn) autoAttendanceBtn.classList.toggle('hidden', tabKey !== 'attendance');
    if (createPeriodBtn) createPeriodBtn.classList.toggle('hidden', tabKey !== 'payroll');

    if (tabKey === 'directory') loadEmployeesData();
    else if (tabKey === 'contracts') loadContractsData();
    else if (tabKey === 'attendance') loadAttendancePeriodsAndData();
    else if (tabKey === 'payroll') loadPayrollPeriodsData();
    else if (tabKey === 'policies') loadPayrollPoliciesData();
}

async function loadEmployeesData() {
    try {
        const [empRes, statsRes] = await Promise.all([
            fetchWithAuth('/api/personnel/employees/'),
            fetchWithAuth('/api/personnel/stats/')
        ]);

        if (statsRes.ok) {
            const statsJson = await statsRes.json();
            const s = statsJson.stats || {};
            const el = id => document.getElementById(id);
            const setTxt = (id, val) => { const elem = el(id); if (elem && val !== undefined) elem.innerText = val; };

            setTxt('hr-kpi-total', s.total || 0);
            setTxt('hr-card-total-line1', s.card_total?.line_1);
            setTxt('hr-card-total-line2', s.card_total?.line_2);

            setTxt('hr-kpi-drivers', s.drivers || 0);
            setTxt('hr-card-drivers-line1', s.card_drivers?.line_1);
            setTxt('hr-card-drivers-line2', s.card_drivers?.line_2);

            const officeCount = s.card_office?.total !== undefined ? s.card_office.total : ((s.dispatchers || 0) + (s.accountants || 0) + (s.sales || 0));
            setTxt('hr-kpi-office', officeCount);
            setTxt('hr-card-office-line1', s.card_office?.line_1);
            setTxt('hr-card-office-line2', s.card_office?.line_2);

            const warningTotal = s.card_compliance?.total !== undefined ? s.card_compliance.total : ((s.expiring_licenses_count || 0) + (s.expiring_contracts_count || 0));
            setTxt('hr-kpi-warning', warningTotal);
            setTxt('hr-card-compliance-line1', s.card_compliance?.line_1);
            setTxt('hr-card-compliance-line2', s.card_compliance?.line_2);

            setTxt('hr-kpi-payroll', s.card_payroll?.total || '-- đ');
            setTxt('hr-card-payroll-line1', s.card_payroll?.line_1);
            setTxt('hr-card-payroll-line2', s.card_payroll?.line_2);
        }

        if (empRes.ok) {
            const empJson = await empRes.json();
            rawEmployeesList = empJson.results || [];
            filterEmployeesTable();
        }
    } catch (err) {
        console.error('Lỗi tải danh sách nhân sự:', err);
    }
}

function filterExpiringItems() {
    switchHRSubTab('contracts');
    const statusSelect = document.getElementById('contract-filter-status');
    if (statusSelect) statusSelect.value = 'ACTIVE';
}

function filterEmployeesTable() {
    const q = (document.getElementById('emp-search-input')?.value || '').trim().toLowerCase();
    const dept = document.getElementById('emp-filter-dept')?.value || 'ALL';
    const role = document.getElementById('emp-filter-role')?.value || 'ALL';
    const status = document.getElementById('emp-filter-status')?.value || 'ALL';

    const filtered = (rawEmployeesList || []).filter(item => {
        const str = `${item.code} ${item.full_name} ${item.nickname || ''} ${item.username || ''} ${item.phone_number || ''} ${item.national_id || ''} ${item.bank_account || ''}`.toLowerCase();
        const matchesQuery = !q || str.includes(q);
        const matchesDept = dept === 'ALL' || item.department === dept;
        const matchesRole = role === 'ALL' || item.role === role;
        const matchesStatus = status === 'ALL' || (status === 'ACTIVE' ? item.is_active : !item.is_active);
        return matchesQuery && matchesDept && matchesRole && matchesStatus;
    });

    const countDisplay = document.getElementById('emp-count-display');
    if (countDisplay) countDisplay.innerText = filtered.length;

    renderEmployeesTable(filtered);
}

function renderEmployeesTable(items) {
    const tbody = document.getElementById('employees-tbody');
    if (!tbody) return;

    if (!items || items.length === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="12" class="p-8 text-center text-slate-400 font-medium">
                    <i class="ph ph-user-circle text-3xl mb-2 text-slate-300 block"></i>
                    Không tìm thấy nhân sự nào phù hợp với bộ lọc.
                </td>
            </tr>
        `;
        return;
    }

    tbody.innerHTML = items.map((emp, index) => {
        const contractInfo = emp.active_contract ? `${emp.active_contract.contract_type_label || 'HĐ'}` : '<span class="text-slate-400">Chưa ký</span>';
        const bankInfo = emp.bank_account ? `<span class="font-mono font-bold">${escapeHtml(emp.bank_account)}</span> (${escapeHtml(emp.bank_name || 'NH')})` : '<span class="text-slate-400">—</span>';
        const legalInfo = emp.national_id ? `<span class="font-mono">${escapeHtml(emp.national_id)}</span>` : '<span class="text-slate-400">—</span>';

        return `
            <tr class="hover:bg-slate-50 transition-colors border-b border-slate-200">
                <td class="py-2.5 px-3.5 text-center font-mono font-bold text-slate-500 border-r border-slate-200 text-xs tabular-nums select-none w-12">${index + 1}</td>
                <td class="py-2.5 px-3.5 font-mono font-bold text-teal-900 border-r border-slate-200 text-xs">${escapeHtml(emp.code)}</td>
                <td class="py-2.5 px-3.5 font-bold text-slate-900 border-r border-slate-200 text-sm">
                    <div class="flex items-center gap-1.5 flex-wrap">
                        <span>${escapeHtml(emp.full_name)}</span>
                        ${emp.nickname ? `<span class="text-xs text-slate-500 font-normal">(${escapeHtml(emp.nickname)})</span>` : ''}
                        ${emp.username ? `<span class="inline-flex items-center gap-1 px-1.5 py-0.5 rounded-md bg-teal-50 text-teal-800 border border-teal-200 text-[10px] font-mono font-bold" title="Tài khoản đăng nhập hệ thống"><i class="ph-bold ph-user"></i>${escapeHtml(emp.username)}</span>` : ''}
                    </div>
                    <div class="text-[11px] text-slate-400 font-normal">${emp.gender_label || ''} ${emp.date_of_birth ? '• ' + emp.date_of_birth : ''}</div>
                </td>
                <td class="py-2.5 px-3.5 text-xs border-r border-slate-200">
                    <div>${legalInfo}</div>
                    ${emp.tax_id ? `<div class="text-[11px] text-slate-500">MST: ${escapeHtml(emp.tax_id)}</div>` : ''}
                </td>
                <td class="py-2.5 px-3.5 text-xs border-r border-slate-200 font-mono">
                    <div class="font-bold text-slate-800">${escapeHtml(emp.phone_number || '—')}</div>
                    ${emp.zalo_id ? `<div class="text-[11px] text-teal-600 font-medium">Zalo: ${escapeHtml(emp.zalo_id)}</div>` : ''}
                </td>
                <td class="py-2.5 px-3.5 text-xs font-medium text-slate-700 border-r border-slate-200">${escapeHtml(emp.department_label || emp.department)}</td>
                <td class="py-2.5 px-3.5 text-xs font-bold border-r border-slate-200">
                    <span class="${emp.role === 'DRIVER' ? 'text-emerald-700' : (emp.role === 'DIRECTOR' ? 'text-purple-700' : 'text-blue-700')}">
                        ${escapeHtml(emp.role_label || emp.role)}
                    </span>
                </td>
                <td class="py-2.5 px-3.5 text-xs border-r border-slate-200">
                    ${emp.license_number ? `
                        <div class="font-mono font-bold text-slate-800">${escapeHtml(emp.license_number)}</div>
                        ${emp.license_expiry ? `<div class="text-[11px] text-slate-500">Hạn: ${emp.license_expiry}</div>` : ''}
                    ` : '<span class="text-slate-400">—</span>'}
                </td>
                <td class="py-2.5 px-3.5 text-xs border-r border-slate-200">${bankInfo}</td>
                <td class="py-2.5 px-3.5 text-xs font-mono font-bold text-right text-slate-900 border-r border-slate-200 tabular-nums">${new Intl.NumberFormat('vi-VN').format(emp.base_salary || 0)} đ</td>
                <td class="py-2.5 px-3.5 text-center border-r border-slate-200 text-xs font-semibold whitespace-nowrap">
                    ${emp.is_active ? '<span class="text-emerald-700 font-bold">Đang làm</span>' : '<span class="text-slate-400 font-medium">Tạm ngưng</span>'}
                </td>
                <td class="py-2.5 px-3.5 text-center">
                    <div class="inline-flex items-center gap-1.5 justify-center">
                        <!-- 1. Xem Nhân Viên (Toàn màn hình) -->
                        <button type="button" onclick="openEditEmployeePage(${emp.id})" 
                            class="px-2.5 py-1 bg-transparent hover:bg-teal-600 text-teal-700 hover:text-white border border-teal-600 rounded-lg text-xs font-bold transition-all inline-flex items-center gap-1 cursor-pointer"
                            title="Xem chi tiết, Sửa, Lưu & Xóa hồ sơ nhân sự">
                            <i class="ph-bold ph-eye"></i>
                            <span>Xem</span>
                        </button>
                        <!-- 2. In nhanh Hồ sơ nhân sự khổ A4 -->
                        <button type="button" onclick="openDirectPrintEmployee(${emp.id})" 
                            class="px-2.5 py-1 bg-transparent hover:bg-slate-700 text-slate-700 hover:text-white border border-slate-600 rounded-lg text-xs font-bold transition-all inline-flex items-center gap-1 cursor-pointer"
                            title="In hồ sơ nhân sự">
                            <i class="ph-bold ph-printer"></i>
                            <span>In</span>
                        </button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');

    if (window.BimTableFooter && Array.isArray(items)) {
        const totalBaseSal = items.reduce((sum, e) => sum + (Number(e.base_salary) || 0), 0);
        window.BimTableFooter.render('employees-table', {
            cells: [
                { text: 'TỔNG', align: 'center', class: 'font-black text-slate-900 font-heading' },
                { html: `<span class="text-teal-800 font-extrabold">${items.length}</span> nhân sự trong danh sách`, colspan: 8, class: 'text-slate-700' },
                { html: `<span class="text-emerald-700 font-bold tabular-nums font-mono">${new Intl.NumberFormat('vi-VN').format(totalBaseSal)} đ</span>`, align: 'right' },
                { text: '', align: 'center' },
                { text: '', align: 'center' }
            ]
        });
    }
}



// ---- src/app/hr/contracts.js ----
// --- SUB-PANEL 2: HỢP ĐỒNG LAO ĐỘNG ---
async function loadContractsData() {
    try {
        const status = document.getElementById('contract-filter-status')?.value || '';
        const url = status ? `/api/personnel/contracts/?status=${status}` : '/api/personnel/contracts/';
        const res = await fetchWithAuth(url);
        if (!res.ok) throw new Error('Lỗi tải danh sách hợp đồng');
        rawContractsList = await res.json();
        
        const badge = document.getElementById('contracts-count-badge');
        if (badge) badge.innerText = `${rawContractsList.length} HĐ`;

        renderContractsTable(rawContractsList);
    } catch (err) {
        console.error('Lỗi tải HĐLĐ:', err);
    }
}

function renderContractsTable(items) {
    const tbody = document.getElementById('contracts-tbody');
    if (!tbody) return;

    if (!items || items.length === 0) {
        tbody.innerHTML = `
            <tr>
                <td colspan="14" class="p-8 text-center text-slate-400 font-medium">
                    <i class="ph ph-file-text text-3xl mb-2 text-slate-300 block"></i>
                    Không có hợp đồng lao động nào.
                </td>
            </tr>
        `;
        return;
    }

    tbody.innerHTML = items.map((c, index) => {
        const isExpiring = c.end_date && new Date(c.end_date) <= new Date(Date.now() + 30 * 86400000);
        const dateBadge = isExpiring && c.status === 'ACTIVE' 
            ? `<span class="text-amber-600 font-bold font-mono">${c.end_date} (Sắp hết hạn)</span>`
            : `<span class="font-mono text-slate-700">${c.end_date || 'Không thời hạn'}</span>`;

        const totalSalaryVal = (c.total_salary !== undefined && c.total_salary !== null) ? c.total_salary : ((c.base_salary || 0) + (c.allowance_amount || 0) + (c.subsidy_amount || 0));
        const allowancesSum = (c.allowance_amount || 0) + (c.subsidy_amount || 0);

        const bhxhBadge = c.is_social_insurance_participant !== false 
            ? `<span class="font-bold text-[11px] text-teal-700" title="Có đóng BHXH">BHXH</span>`
            : `<span class="font-medium text-[11px] text-slate-300" title="Không tham gia BHXH">-</span>`;
        const tncnBadge = c.is_taxable !== false 
            ? `<span class="font-bold text-[11px] text-indigo-700" title="Có tính thuế TNCN">TNCN</span>`
            : `<span class="font-medium text-[11px] text-slate-300" title="Miễn tính thuế">-</span>`;
        const congDoanBadge = c.is_union_member === true 
            ? `<span class="font-bold text-[11px] text-amber-700" title="Đoàn viên công đoàn">CĐ</span>`
            : `<span class="font-medium text-[11px] text-slate-300" title="Không tham gia">-</span>`;

        const deptDisplay = c.department_label || c.department || '—';
        const roleDisplay = c.job_title || c.role_label || c.role || '—';

        return `
            <tr class="hover:bg-slate-50 transition-colors border-b border-slate-200">
                <td class="py-2.5 px-3 text-center font-mono font-bold text-slate-500 border-r border-slate-200 text-xs w-12">${index + 1}</td>
                <td class="py-2.5 px-3 font-mono font-bold text-indigo-900 border-r border-slate-200 text-xs">${escapeHtml(c.contract_number)}</td>
                <td class="py-2.5 px-3 font-bold text-slate-900 border-r border-slate-200 text-xs">
                    <div>${escapeHtml(c.employee_name)}</div>
                    <div class="text-[11px] text-slate-400 font-mono">${escapeHtml(c.employee_code)}</div>
                </td>
                <td class="py-2.5 px-3 text-xs text-slate-700 border-r border-slate-200 whitespace-nowrap">${escapeHtml(c.contract_type_label || c.contract_type)}</td>
                <td class="py-2.5 px-3 text-xs text-slate-700 border-r border-slate-200">
                    <div class="font-bold text-slate-800">${escapeHtml(roleDisplay)}</div>
                    <div class="text-[11px] text-slate-500">${escapeHtml(deptDisplay)}</div>
                </td>
                <td class="py-2.5 px-3 text-xs font-mono border-r border-slate-200 text-center whitespace-nowrap">
                    <div>${c.start_date}</div>
                    <div class="text-[11px]">${dateBadge}</div>
                </td>
                <td class="py-2.5 px-3 text-xs font-mono font-bold text-right text-slate-900 border-r border-slate-200 whitespace-nowrap">${new Intl.NumberFormat('vi-VN').format(c.base_salary || 0)} đ</td>
                <td class="py-2.5 px-3 text-xs font-mono font-medium text-right text-slate-700 border-r border-slate-200 whitespace-nowrap">${allowancesSum > 0 ? new Intl.NumberFormat('vi-VN').format(allowancesSum) + ' đ' : '0 đ'}</td>
                <td class="py-2.5 px-3 text-xs font-mono font-black text-right text-indigo-950 border-r border-slate-200 bg-indigo-50/40 whitespace-nowrap">${new Intl.NumberFormat('vi-VN').format(totalSalaryVal)} đ</td>
                <td class="py-2.5 px-3 text-xs font-mono font-bold text-right text-teal-800 border-r border-slate-200 whitespace-nowrap">${new Intl.NumberFormat('vi-VN').format(c.insurance_salary || 0)} đ</td>
                <td class="py-2.5 px-3 text-center text-xs border-r border-slate-200 whitespace-nowrap">
                    <div class="inline-flex items-center gap-1">
                        ${bhxhBadge}
                        ${tncnBadge}
                        ${congDoanBadge}
                    </div>
                </td>
                <td class="py-2.5 px-3 text-center text-xs border-r border-slate-200 font-bold text-indigo-700">${c.appendices ? c.appendices.length : 0}</td>
                <td class="py-2.5 px-3 text-center text-xs font-bold border-r border-slate-200 whitespace-nowrap">
                    <span class="${c.status === 'ACTIVE' ? 'text-emerald-700' : (c.status === 'EXPIRED' ? 'text-amber-600' : 'text-slate-400')}">
                        ${escapeHtml(c.status_label || c.status)}
                    </span>
                </td>
                <td class="py-2.5 px-3 text-center text-xs whitespace-nowrap">
                    <div class="inline-flex items-center gap-1.5 justify-center">
                        <button type="button" onclick="openContractDetailPage(${c.id})" 
                            class="px-2.5 py-1 bg-transparent hover:bg-teal-600 text-teal-700 hover:text-white border border-teal-600 rounded-lg text-xs font-bold transition-all cursor-pointer inline-flex items-center gap-1"
                            title="Xem chi tiết, Sửa, Lưu, In & Chấm dứt hợp đồng">
                            <i class="ph-bold ph-eye"></i>
                            <span>Xem</span>
                        </button>
                        <button type="button" onclick="openDirectPrintContract(${c.id})" 
                            class="px-2.5 py-1 bg-transparent hover:bg-slate-700 text-slate-700 hover:text-white border border-slate-600 rounded-lg text-xs font-bold transition-all cursor-pointer inline-flex items-center gap-1"
                            title="In hợp đồng lao động khổ A4">
                            <i class="ph-bold ph-printer"></i>
                            <span>In</span>
                        </button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');

    if (window.BimTableFooter && Array.isArray(items)) {
        const totalBaseSalary = items.reduce((sum, c) => sum + (Number(c.base_salary) || 0), 0);
        const totalAllowancesSum = items.reduce((sum, c) => sum + ((Number(c.allowance_amount) || 0) + (Number(c.subsidy_amount) || 0)), 0);
        const totalGrossIncome = items.reduce((sum, c) => sum + ((c.total_salary !== undefined && c.total_salary !== null) ? Number(c.total_salary) : ((Number(c.base_salary) || 0) + (Number(c.allowance_amount) || 0) + (Number(c.subsidy_amount) || 0))), 0);
        const totalInsuranceSalary = items.reduce((sum, c) => sum + (Number(c.insurance_salary || c.base_salary) || 0), 0);
        const totalAppendixCount = items.reduce((sum, c) => sum + (Number(c.appendix_count) || 0), 0);
        window.BimTableFooter.render('contracts-table', {
            cells: [
                { text: 'TỔNG', align: 'center', class: 'font-black text-slate-900 font-heading' },
                { html: `<span class="text-indigo-900 font-extrabold">${items.length}</span> hợp đồng lao động`, colspan: 5, class: 'text-slate-700' },
                { html: `<span class="text-slate-900 font-bold tabular-nums font-mono">${new Intl.NumberFormat('vi-VN').format(totalBaseSalary)} đ</span>`, align: 'right' },
                { html: `<span class="text-slate-700 font-bold tabular-nums font-mono">${new Intl.NumberFormat('vi-VN').format(totalAllowancesSum)} đ</span>`, align: 'right' },
                { html: `<span class="text-indigo-950 font-black tabular-nums font-mono">${new Intl.NumberFormat('vi-VN').format(totalGrossIncome)} đ</span>`, align: 'right' },
                { html: `<span class="text-teal-800 font-bold tabular-nums font-mono">${new Intl.NumberFormat('vi-VN').format(totalInsuranceSalary)} đ</span>`, align: 'right' },
                { text: '', align: 'center' },
                { html: `<span class="font-bold tabular-nums font-mono">${totalAppendixCount}</span>`, align: 'center' },
                { text: '', align: 'center' },
                { text: '', align: 'center' }
            ]
        });
    }
}

// =========================================================================
// MODALS CRUD: HỢP ĐỒNG LAO ĐỘNG, PHỤ LỤC, NGƯỜI PHỤ THUỘC & PHIẾU LƯƠNG
// =========================================================================
// =========================================================================
// PHÂN HỆ QUẢN TRỊ NHÂN SỰ — DEDICATED FULL-PAGE VIEW CONTROLLERS
// (TUÂN THỦ 100%: MỞ TRANG TOÀN MÀN HÌNH, KHÔNG DÙNG MODAL CHE GIAO DIỆN)
// =========================================================================
let cachedEmployeesList = [];
let currentViewingContractId = null;
let currentViewingSlipId = null;

async function populateContractEmployeeDropdown(selectedEmpId = null) {
    try {
        const empSelect = document.getElementById('cd-employee');
        if (!cachedEmployeesList || cachedEmployeesList.length === 0) {
            const res = await fetchWithAuth('/api/personnel/employees/');
            if (res.ok) {
                const data = await res.json();
                cachedEmployeesList = Array.isArray(data) ? data : (data.results || []);
            }
        }
        
        const optionsHtml = '<option value="">-- Chọn nhân sự --</option>' + (cachedEmployeesList || []).map(emp => {
            return `<option value="${emp.id}">[${escapeHtml(emp.code)}] ${escapeHtml(emp.full_name)} (${escapeHtml(emp.role || emp.department || 'Nhân viên')})</option>`;
        }).join('');

        if (empSelect) {
            empSelect.innerHTML = optionsHtml;
            if (selectedEmpId) empSelect.value = selectedEmpId;
        }
    } catch (e) {
        console.error('Lỗi tải danh mục nhân viên:', e);
    }
}

// -------------------------------------------------------------------------
// 1. DEDICATED FULL-PAGE VIEW: HỢP ĐỒNG LAO ĐỘNG (LABOR CONTRACT)
// -------------------------------------------------------------------------
function calculateContractTotalSalary() {
    const baseSal = parseFloat(String(document.getElementById('cd-base-salary')?.value || '0').replace(/\D/g, '')) || 0;
    const allowVal = parseFloat(String(document.getElementById('cd-allowance-amount')?.value || '0').replace(/\D/g, '')) || 0;
    const subVal = parseFloat(String(document.getElementById('cd-subsidy-amount')?.value || '0').replace(/\D/g, '')) || 0;
    const total = baseSal + allowVal + subVal;
    const totalEl = document.getElementById('cd-total-salary');
    if (totalEl) {
        totalEl.value = new Intl.NumberFormat('vi-VN').format(total) + ' đ';
    }
    return total;
}
window.calculateContractTotalSalary = calculateContractTotalSalary;

function getContractTypePrefix(type) {
    if (!type) return 'HDLD';
    const t = String(type).toUpperCase();
    if (t === 'PROBATION') return 'HDTV';
    if (t === 'SEASONAL') return 'HDKV';
    return 'HDLD';
}

async function suggestContractNumber(type = 'DEFINITE_TERM', year = null) {
    const curYear = year || new Date().getFullYear();
    const prefix = getContractTypePrefix(type);
    try {
        const res = await fetchWithAuth(`/api/personnel/contracts/?action=suggest_number&type=${encodeURIComponent(type)}&year=${curYear}`);
        if (res.ok) {
            const data = await res.json();
            if (data.suggested_contract_number) return data.suggested_contract_number;
        }
    } catch (e) {
        console.warn('Lỗi lấy mã HĐ gợi ý từ máy chủ:', e);
    }
    // Fallback tính số tiếp theo nếu mạng chậm
    let maxSeq = 0;
    if (Array.isArray(rawContractsList)) {
        rawContractsList.forEach(c => {
            const num = c.contract_number || '';
            const m = num.match(/\.(\d{1,6})$/);
            if (m) {
                const s = parseInt(m[1], 10);
                if (s > maxSeq) maxSeq = s;
            }
        });
    }
    const nextSeq = String(maxSeq + 1).padStart(4, '0');
    return `${prefix}.${curYear}.${nextSeq}`;
}

function onContractTypeChange() {
    const contractId = document.getElementById('contract-detail-id')?.value;
    if (contractId) return; // Nếu đang chỉnh sửa HĐ đã có ID thì giữ nguyên
    const type = document.getElementById('cd-type')?.value || 'DEFINITE_TERM';
    const numInput = document.getElementById('cd-number');
    if (!numInput) return;
    const curVal = numInput.value.trim();
    const prefix = getContractTypePrefix(type);

    // Nếu mã hiện tại đang khớp format chuẩn: (HDLD|HDTV|HDKV).\d{4}.\d{4}
    const m = curVal.match(/^(HDLD|HDTV|HDKV)\.(\d{4})\.(\d{4})$/);
    if (m) {
        numInput.value = `${prefix}.${m[2]}.${m[3]}`;
    } else {
        suggestContractNumber(type).then(num => {
            if (numInput && !document.getElementById('contract-detail-id')?.value) {
                numInput.value = num;
            }
        });
    }
}

async function openCreateContractPage(employeeId = null, updateHistory = true) {
    currentViewingContractId = null;
    const form = document.getElementById('form-contract-detail');
    if (form) form.reset();
    
    document.getElementById('contract-detail-id').value = '';
    
    // Tự sinh số HĐ chuẩn: [Loại hợp đồng].[Năm].[SốTT trong năm]
    const curYear = new Date().getFullYear();
    const typeSelect = document.getElementById('cd-type');
    const contractType = typeSelect ? typeSelect.value : 'DEFINITE_TERM';
    const numInput = document.getElementById('cd-number');
    if (numInput) {
        numInput.value = 'Đang tạo mã...';
        suggestContractNumber(contractType, curYear).then(suggested => {
            if (numInput && (numInput.value === 'Đang tạo mã...' || !numInput.value)) {
                numInput.value = suggested;
            }
        }).catch(() => {
            if (numInput && (numInput.value === 'Đang tạo mã...' || !numInput.value)) {
                numInput.value = `HDLD.${curYear}.0001`;
            }
        });
    }

    const today = new Date().toISOString().split('T')[0];
    const signInput = document.getElementById('cd-sign-date');
    const startInput = document.getElementById('cd-start-date');
    if (signInput) signInput.value = today;
    if (startInput) startInput.value = today;

    const baseSal = document.getElementById('cd-base-salary');
    const insSal = document.getElementById('cd-insurance-salary');
    if (baseSal) baseSal.value = '7,000,000';
    if (insSal) insSal.value = '5,000,000';

    const allowEl = document.getElementById('cd-allowance-amount');
    const subEl = document.getElementById('cd-subsidy-amount');
    const probEl = document.getElementById('cd-probation-rate');
    const taxTypeEl = document.getElementById('cd-tax-resident-type');
    const isInsEl = document.getElementById('cd-is-insurance');
    const isTaxEl = document.getElementById('cd-is-taxable');
    const isUnionEl = document.getElementById('cd-is-union');

    if (allowEl) allowEl.value = '0';
    if (subEl) subEl.value = '0';
    if (probEl) probEl.value = '100';
    if (taxTypeEl) taxTypeEl.value = 'RESIDENT';
    if (isInsEl) isInsEl.checked = true;
    if (isTaxEl) isTaxEl.checked = true;
    if (isUnionEl) isUnionEl.checked = false;

    calculateContractTotalSalary();

    const statusBadge = document.getElementById('contract-detail-status-badge');
    if (statusBadge) {
        statusBadge.className = 'px-3 py-0.5 rounded-full text-xs font-bold bg-amber-50 text-amber-700 border border-amber-200';
        statusBadge.innerText = 'Dự Thảo (DRAFT)';
    }

    const appCard = document.getElementById('contract-appendices-card');
    if (appCard) appCard.classList.add('hidden'); // Chưa lưu HĐ gốc thì ẩn phụ lục

    await populateContractEmployeeDropdown(employeeId);

    // Nếu truyền employeeId, tự điền phòng ban & vị trí từ nhân viên nếu có
    if (employeeId && Array.isArray(rawEmployeesList)) {
        const selectedEmp = rawEmployeesList.find(e => String(e.id) === String(employeeId));
        if (selectedEmp) {
            const deptEl = document.getElementById('cd-department');
            const roleEl = document.getElementById('cd-role');
            const jobTitleEl = document.getElementById('cd-job-title');
            if (deptEl && selectedEmp.department) deptEl.value = selectedEmp.department;
            if (roleEl && selectedEmp.role) roleEl.value = selectedEmp.role;
            if (jobTitleEl && !jobTitleEl.value) jobTitleEl.value = selectedEmp.role_label || selectedEmp.role || '';
        }
    }

    // Chuyển View sang view-contract-detail
    document.querySelectorAll('.view').forEach(v => v.classList.add('hidden-view'));
    const contractView = document.getElementById('view-contract-detail');
    if (contractView) {
        contractView.classList.remove('hidden-view');
        contractView.scrollTop = 0;
        const innerScroll = contractView.querySelector('.overflow-y-auto');
        if (innerScroll) innerScroll.scrollTop = 0;
    }

    setContractFormReadOnly(false);
    
    const editBtn = document.getElementById('btn-contract-edit-bottom');
    if (editBtn) editBtn.classList.add('hidden');
    const saveBtn = document.getElementById('cd-submit-btn');
    if (saveBtn) {
        saveBtn.disabled = false;
        saveBtn.classList.remove('hidden', 'opacity-50', 'pointer-events-none');
        document.getElementById('cd-submit-btn-text').innerText = 'Lưu Hợp Đồng';
    }
    const printBtn = document.getElementById('btn-contract-print-bottom');
    if (printBtn) printBtn.classList.add('hidden');
    const delBtn = document.getElementById('btn-contract-delete-bottom');
    if (delBtn) delBtn.classList.add('hidden');

    if (typeof setTopbarFullpageMode === 'function') {
        setTopbarFullpageMode({
            backFn: backToContracts,
            prefix: 'Hành Chính & Nhân Sự',
            title: 'Ký Hợp Đồng Lao Động Mới',
            subText: '',
            badgesHtml: '',
            actionsHtml: ''
        });
    }
}

async function openContractDetailPage(contractId, updateHistory = true) {
    currentViewingContractId = contractId;

    try {
        const res = await fetchWithAuth(`/api/personnel/contracts/${contractId}/`);
        if (!res.ok) throw new Error('Không thể tải chi tiết hợp đồng');
        const c = await res.json();

        document.getElementById('contract-detail-id').value = c.id;
        document.getElementById('cd-number').value = c.contract_number || '';
        document.getElementById('cd-type').value = c.contract_type || 'DEFINITE_TERM';
        document.getElementById('cd-status').value = c.status || 'ACTIVE';
        if (document.getElementById('cd-department')) document.getElementById('cd-department').value = c.department || 'FLEET';
        if (document.getElementById('cd-role')) document.getElementById('cd-role').value = c.role || 'DRIVER';
        document.getElementById('cd-job-title').value = c.job_title || '';
        document.getElementById('cd-working-address').value = c.working_address || '';
        document.getElementById('cd-sign-date').value = normalizeDateToISO(c.sign_date) || '';
        document.getElementById('cd-start-date').value = normalizeDateToISO(c.start_date) || '';
        document.getElementById('cd-end-date').value = normalizeDateToISO(c.end_date) || '';
        document.getElementById('cd-base-salary').value = new Intl.NumberFormat('vi-VN').format(c.base_salary || 0);
        document.getElementById('cd-insurance-salary').value = new Intl.NumberFormat('vi-VN').format(c.insurance_salary || 0);
        
        if (document.getElementById('cd-allowance-amount')) document.getElementById('cd-allowance-amount').value = new Intl.NumberFormat('vi-VN').format(c.allowance_amount || 0);
        if (document.getElementById('cd-subsidy-amount')) document.getElementById('cd-subsidy-amount').value = new Intl.NumberFormat('vi-VN').format(c.subsidy_amount || 0);
        if (document.getElementById('cd-probation-rate')) document.getElementById('cd-probation-rate').value = c.probation_rate || 100;
        if (document.getElementById('cd-tax-resident-type')) document.getElementById('cd-tax-resident-type').value = c.tax_resident_type || 'RESIDENT';
        if (document.getElementById('cd-is-insurance')) document.getElementById('cd-is-insurance').checked = c.is_social_insurance_participant !== false;
        if (document.getElementById('cd-is-taxable')) document.getElementById('cd-is-taxable').checked = c.is_taxable !== false;
        if (document.getElementById('cd-is-union')) document.getElementById('cd-is-union').checked = c.is_union_member === true;

        calculateContractTotalSalary();
        document.getElementById('cd-notes').value = c.allowance_notes || c.notes || '';

        const statusBadge = document.getElementById('contract-detail-status-badge');
        if (statusBadge) {
            if (c.status === 'ACTIVE') {
                statusBadge.className = 'px-3 py-0.5 rounded-full text-xs font-bold bg-emerald-50 text-emerald-700 border border-emerald-200';
                statusBadge.innerText = 'Đang Hiệu Lực';
            } else if (c.status === 'EXPIRED') {
                statusBadge.className = 'px-3 py-0.5 rounded-full text-xs font-bold bg-slate-100 text-slate-700 border border-slate-300';
                statusBadge.innerText = 'Đã Hết Hạn';
            } else {
                statusBadge.className = 'px-3 py-0.5 rounded-full text-xs font-bold bg-rose-50 text-rose-700 border border-rose-200';
                statusBadge.innerText = c.status_label || c.status;
            }
        }

        await populateContractEmployeeDropdown(c.employee);

        // Lưu mã phụ lục gợi ý theo chuẩn [Mã HĐ].PL[SốTT]
        if (c.suggested_appendix_number) {
            window._currentContractSuggestedAppendix = c.suggested_appendix_number;
        } else {
            const numHĐ = c.contract_number || '';
            const nextPl = (c.appendices ? c.appendices.length : 0) + 1;
            window._currentContractSuggestedAppendix = `${numHĐ}.PL${nextPl}`;
        }

        // Hiển thị danh sách Phụ Lục HĐ
        const appCard = document.getElementById('contract-appendices-card');
        if (appCard) appCard.classList.remove('hidden');
        renderContractAppendicesList(c.appendices || []);

        // Chuyển sang View view-contract-detail
        document.querySelectorAll('.view').forEach(v => v.classList.add('hidden-view'));
        const contractView = document.getElementById('view-contract-detail');
        if (contractView) {
            contractView.classList.remove('hidden-view');
            contractView.scrollTop = 0;
            const innerScroll = contractView.querySelector('.overflow-y-auto');
            if (innerScroll) innerScroll.scrollTop = 0;
        }

        // Khóa form ở chế độ xem (ReadOnly) và hiện cụm 4 nút chuẩn [Sửa, Lưu, In, Xóa]
        setContractFormReadOnly(true);

        if (typeof setTopbarFullpageMode === 'function') {
            setTopbarFullpageMode({
                backFn: backToContracts,
                prefix: 'Hành Chính & Nhân Sự',
                title: `Hợp Đồng Lao Động | ${c.contract_number} (${c.employee_name || ''})`,
                subText: '',
                badgesHtml: '',
                actionsHtml: ''
            });
        }
    } catch (e) {
        console.error('Lỗi mở chi tiết hợp đồng:', e);
        showToast('error', e.message || 'Không thể mở chi tiết hợp đồng.', 'Lỗi');
    }
}

function renderContractAppendicesList(appendices) {
    const tbody = document.getElementById('contract-appendices-tbody');
    if (!tbody) return;

    if (!appendices || appendices.length === 0) {
        tbody.innerHTML = `<tr><td colspan="8" class="p-4 text-center text-slate-400">Chưa có phụ lục hợp đồng nào được ký kết.</td></tr>`;
        return;
    }

    tbody.innerHTML = appendices.map((app, idx) => `
        <tr class="hover:bg-slate-50 transition-colors">
            <td class="py-2 px-3 text-center font-mono font-bold text-slate-500">${idx + 1}</td>
            <td class="py-2 px-3 font-mono font-bold text-indigo-900">${escapeHtml(app.appendix_number)}</td>
            <td class="py-2 px-3 text-center font-mono">${escapeHtml(app.effective_date || '—')}</td>
            <td class="py-2 px-3 text-right font-mono font-bold text-indigo-950">${app.new_base_salary ? new Intl.NumberFormat('vi-VN').format(app.new_base_salary) + ' đ' : '—'}</td>
            <td class="py-2 px-3 text-right font-mono font-bold text-teal-800">${app.new_insurance_salary ? new Intl.NumberFormat('vi-VN').format(app.new_insurance_salary) + ' đ' : '—'}</td>
            <td class="py-2 px-3 font-medium text-slate-800">${escapeHtml(app.new_role || '—')}</td>
            <td class="py-2 px-3 text-slate-600">${escapeHtml(app.department_label || app.new_department || '—')}</td>
            <td class="py-2 px-3 text-slate-600 max-w-xs truncate">${escapeHtml(app.change_summary || '—')}</td>
        </tr>
    `).join('');
}

function setContractFormReadOnly(isReadOnly) {
    const form = document.getElementById('form-contract-detail');
    if (form) {
        form.querySelectorAll('input:not(#contract-detail-id):not(#cd-total-salary), select, textarea').forEach(el => {
            el.disabled = isReadOnly;
            if (isReadOnly) {
                el.classList.add('bg-slate-50', 'cursor-not-allowed');
            } else {
                el.classList.remove('bg-slate-50', 'cursor-not-allowed');
            }
        });
    }

    const editBtn = document.getElementById('btn-contract-edit-bottom');
    const saveBtn = document.getElementById('cd-submit-btn');
    const printBtn = document.getElementById('btn-contract-print-bottom');
    const delBtn = document.getElementById('btn-contract-delete-bottom');

    if (isReadOnly) {
        if (editBtn) editBtn.classList.remove('hidden');
        if (saveBtn) {
            saveBtn.disabled = true;
            saveBtn.classList.add('opacity-50', 'cursor-not-allowed', 'pointer-events-none');
            document.getElementById('cd-submit-btn-text').innerText = 'Lưu';
        }
        if (printBtn) printBtn.classList.remove('hidden');
        if (delBtn) delBtn.classList.remove('hidden');
    } else {
        if (editBtn) editBtn.classList.add('hidden');
        if (saveBtn) {
            saveBtn.disabled = false;
            saveBtn.classList.remove('hidden', 'opacity-50', 'cursor-not-allowed', 'pointer-events-none');
            document.getElementById('cd-submit-btn-text').innerText = 'Lưu';
        }
    }
}

function enableContractEdit() {
    setContractFormReadOnly(false);
    showToast('info', 'Đã bật chế độ chỉnh sửa hợp đồng. Vui lòng bấm "Lưu" sau khi cập nhật.', 'Chế Độ Sửa');
}

async function submitContractDetailForm(event) {
    if (event && event.preventDefault) event.preventDefault();
    const contractId = document.getElementById('contract-detail-id').value;
    const isEdit = !!contractId;

    const baseSalClean = String(document.getElementById('cd-base-salary').value || '0').replace(/\D/g, '');
    const insSalClean = String(document.getElementById('cd-insurance-salary').value || '0').replace(/\D/g, '');
    const allowClean = String(document.getElementById('cd-allowance-amount')?.value || '0').replace(/\D/g, '');
    const subClean = String(document.getElementById('cd-subsidy-amount')?.value || '0').replace(/\D/g, '');

    const payload = {
        contract_number: document.getElementById('cd-number').value.trim(),
        employee: parseInt(document.getElementById('cd-employee').value),
        contract_type: document.getElementById('cd-type').value,
        status: document.getElementById('cd-status').value,
        department: document.getElementById('cd-department')?.value || 'FLEET',
        role: document.getElementById('cd-role')?.value || 'DRIVER',
        job_title: document.getElementById('cd-job-title').value.trim(),
        working_address: document.getElementById('cd-working-address').value.trim(),
        sign_date: normalizeDateToISO(document.getElementById('cd-sign-date').value),
        start_date: normalizeDateToISO(document.getElementById('cd-start-date').value),
        end_date: normalizeDateToISO(document.getElementById('cd-end-date').value) || null,
        base_salary: parseFloat(baseSalClean) || 0,
        insurance_salary: parseFloat(insSalClean) || 0,
        allowance_amount: parseFloat(allowClean) || 0,
        subsidy_amount: parseFloat(subClean) || 0,
        probation_rate: parseFloat(document.getElementById('cd-probation-rate')?.value) || 100,
        tax_resident_type: document.getElementById('cd-tax-resident-type')?.value || 'RESIDENT',
        is_social_insurance_participant: document.getElementById('cd-is-insurance')?.checked !== false,
        is_taxable: document.getElementById('cd-is-taxable')?.checked !== false,
        is_union_member: document.getElementById('cd-is-union')?.checked === true,
        allowance_notes: document.getElementById('cd-notes').value.trim()
    };

    if (!payload.employee) {
        showToast('warning', 'Vui lòng chọn nhân viên ký hợp đồng.', 'Chú ý');
        return;
    }

    try {
        const url = isEdit ? `/api/personnel/contracts/${contractId}/` : '/api/personnel/contracts/';
        const method = isEdit ? 'PUT' : 'POST';

        const res = await fetchWithAuth(url, {
            method: method,
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });

        const data = await res.json();
        if (!res.ok) {
            const errDetail = data.errors ? Object.entries(data.errors).map(([k, v]) => `${k}: ${v}`).join('; ') : data.message;
            throw new Error(errDetail || 'Không thể lưu hợp đồng.');
        }

        showToast('success', data.message || 'Đã lưu hợp đồng lao động thành công!', 'Thành Công');
        await loadContractsData();
        await loadEmployeesData();

        if (!isEdit && data.data && data.data.id) {
            openContractDetailPage(data.data.id);
        } else {
            setContractFormReadOnly(true);
        }
    } catch (e) {
        console.error('Lỗi lưu hợp đồng:', e);
        showToast('error', e.message || 'Lỗi lưu thông tin hợp đồng.', 'Lỗi Thao Tác');
    }
}

async function confirmDeleteContract() {
    const contractId = document.getElementById('contract-detail-id').value;
    if (!contractId) return;

    let confirmed = false;
    if (typeof showConfirmModal === 'function') {
        confirmed = await showConfirmModal({
            title: 'Chấm Dứt / Xóa Hợp Đồng',
            message: 'Bạn có chắc chắn muốn chuyển trạng thái hợp đồng này sang TERMINATED (Đã chấm dứt)?',
            confirmText: 'Chấm Dứt HĐ',
            cancelText: 'Huỷ Bỏ',
            type: 'danger',
            icon: 'ph-bold ph-x-circle text-2xl'
        });
    } else {
        confirmed = confirm('Bạn có chắc chắn muốn chấm dứt hợp đồng lao động này?');
    }

    if (!confirmed) return;

    try {
        const res = await fetchWithAuth(`/api/personnel/contracts/${contractId}/`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ status: 'TERMINATED' })
        });
        const data = await res.json();
        if (!res.ok) throw new Error(data.message || 'Lỗi chấm dứt hợp đồng');

        showToast('success', 'Đã chấm dứt hiệu lực hợp đồng thành công.', 'Đã Cập Nhật');
        await loadContractsData();
        await loadEmployeesData();
        backToContracts();
    } catch (e) {
        console.error('Lỗi kết thúc HĐ:', e);
        showToast('error', e.message || 'Không thể chấm dứt hợp đồng.', 'Lỗi');
    }
}

function backToContracts() {
    const contractView = document.getElementById('view-contract-detail');
    if (contractView) contractView.classList.add('hidden-view');

    document.querySelectorAll('.view').forEach(v => v.classList.add('hidden-view'));
    const personnelView = document.getElementById('view-nhan-su');
    if (personnelView) personnelView.classList.remove('hidden-view');

    if (typeof resetTopbarStandardMode === 'function') {
        resetTopbarStandardMode('nhan-su');
    }

    if (typeof switchHRSubTab === 'function') {
        switchHRSubTab('contracts');
    }
}

function toggleAddAppendixInline() {
    const box = document.getElementById('inline-appendix-box');
    if (!box) return;

    box.classList.toggle('hidden');
    if (!box.classList.contains('hidden')) {
        const numHĐ = document.getElementById('cd-number')?.value.trim() || '';
        
        let suggestedPl = window._currentContractSuggestedAppendix;
        if (!suggestedPl || !suggestedPl.startsWith(numHĐ)) {
            const tbody = document.getElementById('contract-appendices-tbody');
            const rows = tbody ? tbody.querySelectorAll('tr') : [];
            let maxPl = 0;
            rows.forEach(r => {
                const txt = r.innerText || '';
                const m = txt.match(/\.PL(\d+)/i) || txt.match(/PL-?(\d+)/i);
                if (m) {
                    const s = parseInt(m[1], 10);
                    if (s > maxPl) maxPl = s;
                }
            });
            if (maxPl === 0) {
                const validRows = Array.from(rows).filter(r => !r.innerText.includes('Chưa có phụ lục'));
                maxPl = validRows.length;
            }
            suggestedPl = `${numHĐ}.PL${maxPl + 1}`;
        }

        document.getElementById('inline-app-number').value = suggestedPl;
        document.getElementById('inline-app-date').value = new Date().toISOString().split('T')[0];
        document.getElementById('inline-app-salary').value = document.getElementById('cd-base-salary')?.value || '';
        document.getElementById('inline-app-insurance-salary').value = document.getElementById('cd-insurance-salary')?.value || '';
        document.getElementById('inline-app-allowance').value = document.getElementById('cd-allowance-amount')?.value || '0';
        document.getElementById('inline-app-subsidy').value = document.getElementById('cd-subsidy-amount')?.value || '0';
        document.getElementById('inline-app-department').value = document.getElementById('cd-department')?.value || '';
        document.getElementById('inline-app-role').value = document.getElementById('cd-job-title')?.value || document.getElementById('cd-role')?.value || '';
        document.getElementById('inline-app-summary').value = '';
    }
}

async function submitInlineAppendix() {
    const contractId = document.getElementById('contract-detail-id').value;
    if (!contractId) {
        showToast('warning', 'Vui lòng lưu hợp đồng gốc trước khi ký phụ lục.', 'Chú ý');
        return;
    }

    const salClean = String(document.getElementById('inline-app-salary')?.value || '').replace(/\D/g, '');
    const insClean = String(document.getElementById('inline-app-insurance-salary')?.value || '').replace(/\D/g, '');
    const allowClean = String(document.getElementById('inline-app-allowance')?.value || '').replace(/\D/g, '');
    const subClean = String(document.getElementById('inline-app-subsidy')?.value || '').replace(/\D/g, '');

    const numHĐ = document.getElementById('cd-number')?.value.trim() || '';
    let appNum = document.getElementById('inline-app-number').value.trim();
    if (!appNum) {
        appNum = window._currentContractSuggestedAppendix || `${numHĐ}.PL1`;
    }

    const payload = {
        contract: parseInt(contractId),
        appendix_number: appNum,
        effective_date: normalizeDateToISO(document.getElementById('inline-app-date').value),
        new_base_salary: salClean ? parseFloat(salClean) : null,
        new_insurance_salary: insClean ? parseFloat(insClean) : null,
        new_allowance_amount: allowClean ? parseFloat(allowClean) : null,
        new_subsidy_amount: subClean ? parseFloat(subClean) : null,
        new_department: document.getElementById('inline-app-department')?.value || '',
        new_role: document.getElementById('inline-app-role')?.value.trim() || '',
        change_summary: document.getElementById('inline-app-summary').value.trim()
    };

    if (!payload.appendix_number || !payload.effective_date || !payload.change_summary) {
        showToast('warning', 'Vui lòng nhập đầy đủ Số phụ lục, Ngày hiệu lực và Nội dung điều chỉnh.', 'Thiếu thông tin');
        return;
    }

    try {
        const res = await fetchWithAuth('/api/personnel/appendices/', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
        });
        const data = await res.json();
        if (!res.ok) throw new Error(data.message || 'Lỗi thêm phụ lục hợp đồng');

        showToast('success', data.message || 'Đã thêm phụ lục hợp đồng thành công.', 'Thành Công');
        toggleAddAppendixInline();
        openContractDetailPage(contractId);
    } catch (err) {
        console.error('Lỗi lưu phụ lục:', err);
        showToast('error', err.message || 'Không thể lưu phụ lục hợp đồng.', 'Lỗi');
    }
}

