// ---- src/app/accounting/bot-audit.js ----
// ==============================================================================
// 9.7. SUBTAB 7: ĐỐI SOÁT VÉ CẦU ĐƯỜNG BOT / ETC (BOT AUDIT CONTROLLER)
// ==============================================================================
async function loadBotAuditData() {
    try {
        const globalDates = getDateRangeForPeriod(currentDashboardPeriod, currentDashboardCustomStart, currentDashboardCustomEnd);
        const res = await fetchWithAuth(`/api/accounting/bot-audit/?from_date=${globalDates.fromDate}&to_date=${globalDates.toDate}`);
        if (!res.ok) throw new Error('Không thể tải đối soát vé BOT');
        const data = await res.json();

        // Cập nhật KPIs
        if (data.kpis) {
            const kp = data.kpis;
            const elTrips = document.getElementById('bot-stat-trips');
            if (elTrips) elTrips.innerText = `${kp.total_trips_with_toll} chuyến`;

            const elActual = document.getElementById('bot-stat-actual');
            if (elActual) elActual.innerText = formatMoneyVND(kp.total_actual_toll);

            const elStd = document.getElementById('bot-stat-standard');
            if (elStd) elStd.innerText = formatMoneyVND(kp.total_standard_toll);

            const elVar = document.getElementById('bot-stat-variance');
            if (elVar) elVar.innerText = `${kp.variance_count} chuyến`;
        }

        renderBotAuditTable(data.items || []);
    } catch (err) {
        console.error('Lỗi tải đối soát BOT:', err);
        showToast('danger', 'Không thể kết nối máy chủ để tải đối soát vé BOT', 'Lỗi Đối Soát BOT');
    }
}

function renderBotAuditTable(list) {
    const tbody = document.getElementById('acct-bot-tbody');
    if (!tbody) return;

    if (!list || list.length === 0) {
        tbody.innerHTML = `<tr><td colspan="11" class="p-8 text-center text-slate-400 font-medium">Không tìm thấy dữ liệu vé cầu đường BOT nào</td></tr>`;
        return;
    }

    tbody.innerHTML = list.map((item, index) => {
        let badge = '<span class="text-xs font-semibold text-slate-600 uppercase">Bình thường</span>';
        if (item.warning_level === 'HIGH') {
            badge = `<span class="text-xs font-bold text-rose-700 uppercase">⚠️ Vượt (+${item.variance_percent}%)</span>`;
        } else if (item.warning_level === 'SAVING') {
            badge = `<span class="text-xs font-bold text-emerald-700 uppercase">✅ Tiết kiệm (${item.variance_percent}%)</span>`;
        } else if (item.warning_level === 'NO_STANDARD') {
            badge = '<span class="text-xs text-slate-400 italic">Chưa có định mức</span>';
        }

        const diffClass = item.variance_amount > 0 ? 'text-rose-600' : (item.variance_amount < 0 ? 'text-emerald-600' : 'text-slate-600');
        const diffSign = item.variance_amount > 0 ? '+' : '';

        // Tóm tắt các vé
        const ticketsDesc = (item.tickets_detail || []).map(tk => 
            `<span class="text-[11px] text-slate-700 font-mono mr-1.5" title="${escapeHtml(tk.invoice_issuer || '')}">${formatMoneyVND(tk.amount)}</span>`
        ).join('· ');

        return `
            <tr class="hover:bg-slate-50 transition-colors">
                <td class="w-12 text-center select-none font-bold text-slate-500 border-r border-slate-200 font-mono text-xs tabular-nums">${index + 1}</td>
                <td>
                    <div class="font-bold text-slate-900 font-heading">${escapeHtml(item.trip_code)}</div>
                </td>
                <td>
                    <div class="font-bold text-slate-900 font-mono text-xs">${escapeHtml(item.vehicle_plate)}</div>
                </td>
                <td>
                    <div class="font-semibold text-slate-800">${escapeHtml(item.driver_name)}</div>
                </td>
                <td>
                    <div class="font-medium text-slate-700 text-xs">${escapeHtml(item.route_name)}</div>
                </td>
                <td class="text-center font-bold text-slate-800">${item.tickets_count} vé</td>
                <td class="text-right font-black text-rose-700 tabular-nums font-heading">
                    ${formatMoneyVND(item.actual_toll)}
                </td>
                <td class="text-right font-bold text-indigo-700 tabular-nums">
                    ${item.standard_toll > 0 ? formatMoneyVND(item.standard_toll) : '<span class="text-slate-400">-</span>'}
                </td>
                <td class="text-right font-black tabular-nums ${diffClass}">
                    ${item.standard_toll > 0 ? `${diffSign}${formatMoneyVND(item.variance_amount)}` : '<span class="text-slate-400">-</span>'}
                </td>
                <td class="text-center">${badge}</td>
                <td>
                    <div class="flex flex-wrap gap-1 items-center">
                        ${ticketsDesc || '<span class="text-slate-400">-</span>'}
                    </div>
                </td>
            </tr>
        `;
    }).join('');

    if (window.BimTableFooter && Array.isArray(list)) {
        const totalTickets = list.reduce((sum, i) => sum + (Number(i.tickets_count) || 0), 0);
        const totalActual = list.reduce((sum, i) => sum + (Number(i.actual_toll) || 0), 0);
        const totalStandard = list.reduce((sum, i) => sum + (Number(i.standard_toll) || 0), 0);
        const totalDiff = totalActual - totalStandard;
        window.BimTableFooter.render('accounting-bot-table', {
            cells: [
                { text: 'TỔNG', align: 'center', class: 'font-black text-slate-900 font-heading' },
                { html: `${list.length} chuyến đối soát BOT`, colspan: 4 },
                { html: `<span class="text-slate-800 font-bold tabular-nums font-mono">${totalTickets} vé</span>`, align: 'center' },
                { html: `<span class="text-rose-700 font-bold tabular-nums font-mono">${formatMoneyVND(totalActual)}</span>`, align: 'right' },
                { html: `<span class="text-indigo-700 font-bold tabular-nums font-mono">${formatMoneyVND(totalStandard)}</span>`, align: 'right' },
                { html: `<span class="${totalDiff > 0 ? 'text-rose-600' : 'text-emerald-600'} font-black tabular-nums font-mono">${totalDiff > 0 ? '+' : ''}${formatMoneyVND(totalDiff)}</span>`, align: 'right' },
                { text: '', align: 'center', colspan: 2 }
            ]
        });
    }
}

function exportBotAuditToExcel() {
    exportAccountingToExcel();
}

// applyDispatcherFundsFilter is defined above

function applyBotAuditFilter() {
    const q = (document.getElementById('bot-search')?.value || '').toLowerCase().trim();
    const rows = document.querySelectorAll('#acct-bot-tbody tr');
    rows.forEach(r => {
        if (!q) { r.style.display = ''; return; }
        r.style.display = r.innerText.toLowerCase().includes(q) ? '' : 'none';
    });
}

// ---- src/app/accounting/ledger.js ----
// ==============================================================================
// 9.9. SUBTAB 9: SỔ SÁCH KẾ TOÁN — cân đối tài khoản, nhật ký chung, sổ cái (ánh xạ tài khoản nay nằm ở Cài đặt > Tài chính & Quản trị > Cài đặt tài khoản)
// Dữ liệu từ /api/ledger/* (sổ kép tự động theo chế độ kế toán TT99/TT58 của công ty)
// ==============================================================================
let ledgerView = 'trial';
let ledgerAccounts = null;

const LEDGER_TITLES = {
    trial: 'Bảng cân đối tài khoản',
    journal: 'Sổ nhật ký chung',
    account: 'Sổ cái',
};

function _ledgerNum(n) {
    const v = Number(n || 0);
    return v ? new Intl.NumberFormat('vi-VN').format(Math.round(v)) : '';
}

function _ledgerEsc(s) {
    return (typeof escapeHtml === 'function') ? escapeHtml(s == null ? '' : String(s)) : String(s == null ? '' : s);
}

function _ledgerDate(d) {
    if (!d) return '';
    const p = String(d).slice(0, 10).split('-');
    return p.length === 3 ? `${p[2]}/${p[1]}/${p[0]}` : d;
}

function _ledgerEmpty(view, text) {
    const cols = { trial: 8, journal: 7, account: 7 }[view];
    const tb = document.getElementById(`ledger-${view}-tbody`);
    if (tb) tb.innerHTML = `<tr><td colspan="${cols}" class="p-8 text-center text-slate-400 font-medium">${text}</td></tr>`;
    const tf = document.getElementById(`ledger-${view}-tfoot`);
    if (tf) tf.innerHTML = '';
}

function _ledgerPeriod() {
    const fromEl = document.getElementById('ledger-from');
    const toEl = document.getElementById('ledger-to');
    if (fromEl && !fromEl.value) {
        const now = new Date();
        const pad = (x) => String(x).padStart(2, '0');
        fromEl.value = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-01`;
        toEl.value = `${now.getFullYear()}-${pad(now.getMonth() + 1)}-${pad(now.getDate())}`;
    }
    return { from: fromEl ? fromEl.value : '', to: toEl ? toEl.value : '' };
}

function _ledgerUrl(view, extra = '') {
    const p = _ledgerPeriod();
    const q = `from=${encodeURIComponent(p.from)}&to=${encodeURIComponent(p.to)}${extra}`;
    if (view === 'trial') return `/api/ledger/trial-balance/?${q}`;
    if (view === 'journal') return `/api/ledger/journal/?${q}`;
    const code = (document.getElementById('ledger-account-select') || {}).value || '111';
    return `/api/ledger/accounts/${encodeURIComponent(code)}/ledger/?${q}`;
}

function _ledgerSetHeader(subtitle, summary) {
    const t = document.getElementById('ledger-title');
    if (t) t.textContent = ledgerView === 'account'
        ? `Sổ cái tài khoản ${(document.getElementById('ledger-account-select') || {}).value || ''}`
        : LEDGER_TITLES[ledgerView];
    const s = document.getElementById('ledger-subtitle');
    if (s) s.textContent = subtitle || '';
    const m = document.getElementById('ledger-summary');
    if (m) m.textContent = summary || '';
}

async function loadLedgerData() {
    if (!ledgerAccounts) {
        try {
            const res = await fetchWithAuth('/api/ledger/accounts/');
            if (res.status === 403) {
                ['trial', 'journal', 'account'].forEach(v => _ledgerEmpty(v, 'Chỉ Kế toán và Ban Giám Đốc được xem sổ sách kế toán'));
                return;
            }
            const data = await res.json();
            ledgerAccounts = data.accounts || [];
            const chip = document.getElementById('ledger-regime-chip');
            if (chip) chip.textContent = ({ TT99: 'TT99/2025', TT58: 'TT58/2026', TT200: 'TT200/2014', TT133: 'TT133/2016' })[data.regime] || data.regime;
            const sel = document.getElementById('ledger-account-select');
            if (sel) {
                sel.innerHTML = ledgerAccounts.map(a =>
                    `<option value="${_ledgerEsc(a.code)}">${_ledgerEsc(a.code)} – ${_ledgerEsc(a.name)}</option>`).join('');
                sel.value = '111';
            }
        } catch (err) {
            console.error('Lỗi tải hệ thống tài khoản:', err);
        }
    }
    switchLedgerView(ledgerView);
}

function switchLedgerView(view) {
    ledgerView = view;
    document.querySelectorAll('.ledger-view-btn').forEach(btn => {
        const on = btn.dataset.ledgerView === view;
        btn.classList.toggle('border-indigo-600', on);
        btn.classList.toggle('bg-indigo-50', on);
        btn.classList.toggle('text-indigo-900', on);
        btn.classList.toggle('border-transparent', !on);
        btn.classList.toggle('text-slate-600', !on);
    });
    document.querySelectorAll('.ledger-panel').forEach(p => p.classList.toggle('hidden', p.dataset.ledgerPanel !== view));
    const sel = document.getElementById('ledger-account-select');
    if (sel) sel.classList.toggle('hidden', view !== 'account');
    loadLedgerView();
}

async function loadLedgerView() {
    const view = ledgerView;
    _ledgerSetHeader('', '');
    try {
        const res = await fetchWithAuth(_ledgerUrl(view));
        if (!res.ok) {
            let msg = 'Không tải được sổ';
            try { msg = (await res.json()).detail || msg; } catch (e) { /* bỏ qua */ }
            _ledgerEmpty(view, _ledgerEsc(msg));
            return;
        }
        const data = await res.json();
        if (view !== ledgerView) return;
        if (view === 'trial') renderLedgerTrial(data);
        else if (view === 'journal') renderLedgerJournal(data);
        else renderLedgerAccount(data);
    } catch (err) {
        console.error('Lỗi tải sổ sách:', err);
        _ledgerEmpty(view, 'Không kết nối được máy chủ');
    }
}

function renderLedgerTrial(data) {
    const rows = (data.rows || []).filter(r =>
        r.opening_debit || r.opening_credit || r.period_debit || r.period_credit || r.closing_debit || r.closing_credit);
    _ledgerSetHeader(`Mẫu ${data.form || ''} · ${_ledgerDate(data.from)} – ${_ledgerDate(data.to)}`,
        `${rows.filter(r => r.level === 1).length} tài khoản có số liệu`);
    if (!rows.length) return _ledgerEmpty('trial', 'Chưa có số liệu trong kỳ');
    document.getElementById('ledger-trial-tbody').innerHTML = rows.map(r => {
        const sub = r.level !== 1;
        return `<tr class="${sub ? 'text-slate-500' : 'font-semibold text-slate-800'} cursor-pointer hover:bg-indigo-50/40" onclick="openLedgerAccount('${_ledgerEsc(r.code)}')" title="Xem sổ cái ${_ledgerEsc(r.code)}">
            <td class="font-mono ${sub ? 'pl-6' : ''}">${_ledgerEsc(r.code)}</td>
            <td class="whitespace-normal min-w-[220px]"><span class="md:hidden font-mono">${_ledgerEsc(r.code)} · </span>${_ledgerEsc(r.name)}</td>
            <td class="text-right tabular-nums">${_ledgerNum(r.opening_debit)}</td>
            <td class="text-right tabular-nums">${_ledgerNum(r.opening_credit)}</td>
            <td class="text-right tabular-nums">${_ledgerNum(r.period_debit)}</td>
            <td class="text-right tabular-nums">${_ledgerNum(r.period_credit)}</td>
            <td class="text-right tabular-nums">${_ledgerNum(r.closing_debit)}</td>
            <td class="text-right tabular-nums">${_ledgerNum(r.closing_credit)}</td>
        </tr>`;
    }).join('');
    const t = data.totals || {};
    document.getElementById('ledger-trial-tfoot').innerHTML = `<tr class="bg-slate-100 font-black text-slate-900">
        <td></td><td>Tổng cộng</td>
        <td class="text-right tabular-nums">${_ledgerNum(t.opening_debit)}</td>
        <td class="text-right tabular-nums">${_ledgerNum(t.opening_credit)}</td>
        <td class="text-right tabular-nums">${_ledgerNum(t.period_debit)}</td>
        <td class="text-right tabular-nums">${_ledgerNum(t.period_credit)}</td>
        <td class="text-right tabular-nums">${_ledgerNum(t.closing_debit)}</td>
        <td class="text-right tabular-nums">${_ledgerNum(t.closing_credit)}</td></tr>`;
}

function renderLedgerJournal(data) {
    const lines = data.lines || [];
    const sumD = lines.reduce((a, l) => a + Number(l.debit || 0), 0);
    const sumC = lines.reduce((a, l) => a + Number(l.credit || 0), 0);
    _ledgerSetHeader(`${_ledgerDate(data.from)} – ${_ledgerDate(data.to)}`, `${lines.length} dòng`);
    if (!lines.length) return _ledgerEmpty('journal', 'Chưa có bút toán trong kỳ');
    let prevRef = null;
    document.getElementById('ledger-journal-tbody').innerHTML = lines.map(l => {
        const first = l.ref !== prevRef;
        prevRef = l.ref;
        return `<tr class="${first ? 'border-t border-slate-200' : ''}">
            <td class="tabular-nums">${first ? _ledgerDate(l.date) : ''}</td>
            <td class="font-mono text-xs">${first ? _ledgerEsc(l.ref) : ''}</td>
            <td class="whitespace-normal min-w-[240px] text-slate-700">${_ledgerEsc(l.memo || l.description)}</td>
            <td class="font-mono font-bold">${_ledgerEsc(l.account)}</td>
            <td class="text-right tabular-nums">${_ledgerNum(l.debit)}</td>
            <td class="text-right tabular-nums">${_ledgerNum(l.credit)}</td>
            <td class="text-slate-500">${_ledgerEsc(l.partner)}</td>
        </tr>`;
    }).join('');
    document.getElementById('ledger-journal-tfoot').innerHTML = `<tr class="bg-slate-100 font-black text-slate-900">
        <td></td><td></td><td>Tổng phát sinh</td><td></td>
        <td class="text-right tabular-nums">${_ledgerNum(sumD)}</td>
        <td class="text-right tabular-nums">${_ledgerNum(sumC)}</td><td></td></tr>`;
}

function renderLedgerAccount(data) {
    const rows = data.rows || [];
    _ledgerSetHeader(`${_ledgerDate(data.from)} – ${_ledgerDate(data.to)}`,
        `Đầu kỳ ${_ledgerNum(data.opening) || 0} · Cuối kỳ ${_ledgerNum(data.closing) || 0}`);
    const opening = `<tr class="bg-slate-50 font-bold text-slate-700">
        <td></td><td></td><td>Số dư đầu kỳ</td><td></td>
        <td></td><td></td><td class="text-right tabular-nums">${_ledgerNum(data.opening) || 0}</td></tr>`;
    const body = rows.map(r => `<tr>
        <td class="tabular-nums">${_ledgerDate(r.date)}</td>
        <td class="font-mono text-xs">${_ledgerEsc(r.ref)}</td>
        <td class="whitespace-normal min-w-[240px] text-slate-700">${_ledgerEsc(r.description)}</td>
        <td class="font-mono">${_ledgerEsc(r.contra)}</td>
        <td class="text-right tabular-nums">${_ledgerNum(r.debit)}</td>
        <td class="text-right tabular-nums">${_ledgerNum(r.credit)}</td>
        <td class="text-right tabular-nums font-semibold">${_ledgerNum(r.balance) || 0}</td></tr>`).join('');
    document.getElementById('ledger-account-tbody').innerHTML = opening + (body ||
        `<tr><td colspan="7" class="p-6 text-center text-slate-400 font-medium">Không có phát sinh trong kỳ</td></tr>`);
    const sumD = rows.reduce((a, r) => a + Number(r.debit || 0), 0);
    const sumC = rows.reduce((a, r) => a + Number(r.credit || 0), 0);
    document.getElementById('ledger-account-tfoot').innerHTML = `<tr class="bg-slate-100 font-black text-slate-900">
        <td></td><td></td><td>Cộng phát sinh · Số dư cuối kỳ</td><td></td>
        <td class="text-right tabular-nums">${_ledgerNum(sumD)}</td>
        <td class="text-right tabular-nums">${_ledgerNum(sumC)}</td>
        <td class="text-right tabular-nums">${_ledgerNum(data.closing) || 0}</td></tr>`;
}

function openLedgerAccount(code) {
    const sel = document.getElementById('ledger-account-select');
    if (sel) {
        if (!Array.from(sel.options).some(o => o.value === code)) {
            sel.insertAdjacentHTML('beforeend', `<option value="${_ledgerEsc(code)}">${_ledgerEsc(code)}</option>`);
        }
        sel.value = code;
    }
    switchLedgerView('account');
}

async function exportLedgerExcel() {
    const btn = document.getElementById('ledger-export-btn');
    if (btn) btn.disabled = true;
    try {
        const res = await fetchWithAuth(_ledgerUrl(ledgerView, '&export=xlsx'));
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        let filename = 'so-sach-ke-toan.xlsx';
        const disp = res.headers.get('Content-Disposition');
        const m = disp && disp.match(/filename="?([^";]+)"?/);
        if (m) filename = m[1];
        const url = URL.createObjectURL(await res.blob());
        const a = document.createElement('a');
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        a.remove();
        URL.revokeObjectURL(url);
        showToast('success', `Đã tải "${filename}"`, 'Xuất Excel');
    } catch (err) {
        console.error('Lỗi xuất sổ:', err);
        showToast('danger', 'Không xuất được file Excel', 'Xuất Excel');
    } finally {
        if (btn) btn.disabled = false;
    }
}

// ---- src/app/accounting/customer-settlement.js ----
let customerSettlementsCache = [];
let customerSettlementsSummary = {};
let selectedCustTripIds = new Set();
let custSettleSortColumn = null;
let custSettleSortDirection = 'asc';

function toggleCustomerSettleSort(col) {
    if (custSettleSortColumn === col) {
        custSettleSortDirection = custSettleSortDirection === 'asc' ? 'desc' : 'asc';
    } else {
        custSettleSortColumn = col;
        custSettleSortDirection = 'asc';
    }
    applyCustSettleSortAndRender();
}

function filterCustomerSettlementsClientSide() {
    applyCustSettleSortAndRender();
}

function applyCustSettleSortAndRender() {
    if (!customerSettlementsCache || !Array.isArray(customerSettlementsCache)) return;
    let list = [...customerSettlementsCache];

    const searchInput = document.getElementById('cust-settle-search-input');
    const term = searchInput ? searchInput.value.trim().toLowerCase() : '';
    if (term) {
        list = list.filter(t => {
            const code = (t.trip_code || '').toLowerCase();
            const cust = (t.customer_name || '').toLowerCase();
            const cont = (t.container_number || '').toLowerCase();
            const route = (t.route || '').toLowerCase();
            return code.includes(term) || cust.includes(term) || cont.includes(term) || route.includes(term);
        });
    }

    if (custSettleSortColumn) {
        list.sort((a, b) => {
            let valA = a[custSettleSortColumn];
            let valB = b[custSettleSortColumn];

            if (typeof valA === 'string') valA = valA.toLowerCase();
            if (typeof valB === 'string') valB = valB.toLowerCase();
            if (valA == null) valA = '';
            if (valB == null) valB = '';

            if (valA < valB) return custSettleSortDirection === 'asc' ? -1 : 1;
            if (valA > valB) return custSettleSortDirection === 'asc' ? 1 : -1;
            return 0;
        });
    }

    // Cập nhật icon thead
    const sortCols = ['trip_code', 'loading_date', 'customer_name', 'revenue', 'reimbursable', 'total_receivable'];
    sortCols.forEach(col => {
        const iconEl = document.getElementById(`sort-icon-cust-${col}`);
        if (iconEl) {
            if (custSettleSortColumn === col) {
                iconEl.className = custSettleSortDirection === 'asc'
                    ? 'ph-bold ph-arrow-up text-emerald-600 text-xs'
                    : 'ph-bold ph-arrow-down text-emerald-600 text-xs';
            } else {
                iconEl.className = 'ph-bold ph-arrows-down-up text-slate-400 text-xs';
            }
        }
    });

    renderCustomerSettlementsTable(list);
}

async function loadCustomerSettlementsData() {
    const custId = document.getElementById('cust-settle-filter-customer')?.value || '';
    const fromDate = document.getElementById('cust-settle-filter-from-date')?.value || '';
    const toDate = document.getElementById('cust-settle-filter-to-date')?.value || '';
    const statusVal = document.getElementById('cust-settle-filter-status')?.value || 'ALL';

    const tbody = document.getElementById('cust-settle-tbody');
    if (tbody) {
        tbody.innerHTML = `<tr><td colspan="13" class="p-8 text-center text-slate-400 italic"><i class="ph-bold ph-spinner animate-spin text-lg block mb-1"></i> Đang tải dữ liệu quyết toán khách hàng...</td></tr>`;
    }

    try {
        const params = new URLSearchParams({
            customer_id: custId,
            from_date: fromDate,
            to_date: toDate,
            status: statusVal
        });
        const res = await fetchWithAuth(`/api/accounting/customer-reconciliation/?${params.toString()}`);
        if (!res.ok) throw new Error('Không thể tải dữ liệu quyết toán khách hàng');
        const data = await res.json();
        customerSettlementsCache = data.trips || [];
        customerSettlementsSummary = data.summary || {};

        const elFreight = document.getElementById('cust-settle-stat-freight');
        if (elFreight) elFreight.innerText = formatMoneyVND(data.summary?.total_revenue || 0);

        const elReimb = document.getElementById('cust-settle-stat-reimb');
        if (elReimb) elReimb.innerText = formatMoneyVND(data.summary?.total_reimbursable || 0);

        const elTotal = document.getElementById('cust-settle-stat-total');
        if (elTotal) elTotal.innerText = formatMoneyVND(data.summary?.total_receivable || 0);

        const elTrips = document.getElementById('cust-settle-stat-trips');
        if (elTrips) elTrips.innerText = `${data.summary?.pending_trips || 0} / ${data.summary?.total_trips || 0} Chuyến`;

        const elTripsSub = document.getElementById('cust-settle-stat-trips-sub');
        if (elTripsSub) elTripsSub.innerText = `Chờ quyết toán: ${data.summary?.pending_trips || 0} | Đã chốt: ${data.summary?.settled_trips || 0}`;

        const badgeTab = document.getElementById('badge-acct-customer-settlements');
        if (badgeTab) badgeTab.innerText = data.summary?.pending_trips || 0;

        const countEl = document.getElementById('cust-settle-count-badge');
        if (countEl) countEl.innerText = `${customerSettlementsCache.length} chuyến`;

        // Bỏ chọn các chuyến không còn tồn tại
        const availableIds = new Set(customerSettlementsCache.map(t => t.id));
        for (const id of selectedCustTripIds) {
            if (!availableIds.has(id)) selectedCustTripIds.delete(id);
        }

        populateCustomerSettleFilter();
        applyCustSettleSortAndRender();
        updateCustBatchSettleButtonState();
    } catch (err) {
        console.error('Error loading customer settlements:', err);
        if (tbody) {
            tbody.innerHTML = `<tr><td colspan="13" class="p-8 text-center text-rose-500 font-bold"><i class="ph-bold ph-warning text-lg block mb-1"></i> Lỗi nạp dữ liệu: ${escapeHtml(err.message)}</td></tr>`;
        }
    }
}

function populateCustomerSettleFilter() {
    const sel = document.getElementById('cust-settle-filter-customer');
    if (!sel || sel.children.length > 1) return;
    const custMap = new Map();
    customerSettlementsCache.forEach(t => {
        if (t.customer_id && t.customer_name) {
            custMap.set(String(t.customer_id), t.customer_name);
        }
    });
    custMap.forEach((name, id) => {
        const opt = document.createElement('option');
        opt.value = id;
        opt.innerText = name;
        sel.appendChild(opt);
    });
}

function renderCustomerSettlementsTable(list = null) {
    const displayList = list !== null ? list : customerSettlementsCache;
    const tbody = document.getElementById('cust-settle-tbody');
    if (!tbody) return;

    if (!displayList || displayList.length === 0) {
        tbody.innerHTML = `<tr><td colspan="13" class="p-8 text-center text-slate-400 italic">Không có chuyến xe nào theo điều kiện lọc đã chọn</td></tr>`;
        return;
    }

    tbody.innerHTML = displayList.map((t, idx) => {
        const isSettled = !!t.is_customer_settled;
        const isChecked = selectedCustTripIds.has(t.id);
        const chkDisabled = isSettled ? 'disabled title="Chuyến này đã quyết toán xong"' : '';
        const chkClass = isSettled ? 'opacity-30 cursor-not-allowed' : 'cursor-pointer';

        const statusBadge = isSettled
            ? `<span class="text-emerald-700 font-bold flex items-center gap-1 justify-center text-xs"><i class="ph-bold ph-check-circle text-xs"></i> Đã Quyết Toán</span>`
            : `<span class="text-amber-600 font-bold flex items-center gap-1 justify-center text-xs"><i class="ph-bold ph-clock text-xs"></i> Chờ Quyết Toán</span>`;

        const podBadge = t.has_pod
            ? `<span class="text-emerald-700 font-bold flex items-center gap-1 justify-center text-xs"><i class="ph-bold ph-check-circle text-xs"></i> Đầy đủ</span>`
            : `<span class="text-slate-400 font-medium flex items-center gap-1 justify-center text-xs"><i class="ph-bold ph-clock text-xs"></i> Chưa có</span>`;

        return `
            <tr class="hover:bg-slate-50/80 transition-colors ${isChecked ? 'bg-emerald-50/40' : ''}">
                <td class="w-10 text-center border-r border-slate-200">
                    <input type="checkbox"
                        class="cust-settle-row-checkbox rounded border-slate-300 text-teal-600 focus:ring-teal-500 w-4 h-4 ${chkClass}"
                        data-trip-id="${t.id}"
                        ${isChecked ? 'checked' : ''}
                        ${chkDisabled}
                        onchange="onCustSettleTripSelectionChange(${t.id}, this.checked)">
                </td>
                <td class="w-12 text-center select-none font-bold text-slate-500 border-r border-slate-200 font-mono text-xs tabular-nums">${idx + 1}</td>
                <td class="p-3 font-mono font-bold text-teal-900">${escapeHtml(t.trip_code)}</td>
                <td class="p-3 font-semibold text-slate-700 whitespace-nowrap text-center">${escapeHtml(t.loading_date)}</td>
                <td class="p-3 font-bold text-slate-900 max-w-[200px] truncate" title="${escapeHtml(t.customer_name)}">${escapeHtml(t.customer_name)}</td>
                <td class="p-3 font-mono text-slate-700">${escapeHtml(t.container_number || '-')}</td>
                <td class="p-3 text-slate-600 text-[11px] max-w-[220px] truncate" title="${escapeHtml(t.route)}">${escapeHtml(t.route)}</td>
                <td class="p-3 font-mono font-bold text-teal-800 text-right tabular-nums">${formatMoneyVND(t.revenue || 0)}</td>
                <td class="p-3 font-mono font-semibold text-amber-700 text-right tabular-nums">${formatMoneyVND(t.reimbursable || 0)}</td>
                <td class="p-3 font-mono font-black text-slate-900 text-right tabular-nums bg-slate-50/50">${formatMoneyVND(t.total_receivable || 0)}</td>
                <td class="p-3 text-center">${podBadge}</td>
                <td class="p-3 text-center">${statusBadge}</td>
                <td class="p-3 text-center cell-actions whitespace-nowrap">
                    <div class="flex items-center justify-center gap-1.5">
                        <!-- 1. Quyết toán -->
                        ${isSettled ? `
                            <button type="button" onclick="toggleCustomerSettleSingle(${t.id}, 'UNSETTLE')" title="Mở lại quyết toán doanh thu khách hàng" 
                                class="h-7 px-2.5 text-[11px] font-bold text-slate-600 hover:text-slate-900 bg-slate-100 hover:bg-slate-200 rounded-lg transition-colors border border-slate-200 inline-flex items-center gap-1 cursor-pointer">
                                <i class="ph-bold ph-arrow-counter-clockwise text-xs"></i><span>Mở Lại</span>
                            </button>
                        ` : `
                            <button type="button" onclick="openSettlementStatement('CUSTOMER', [${t.id}], { with_cash: false })" title="Lập bảng kê quyết toán khách hàng" 
                                class="h-7 px-2.5 text-[11px] font-bold text-white bg-emerald-700 hover:bg-emerald-800 rounded-lg transition-colors shadow-2xs inline-flex items-center gap-1 cursor-pointer">
                                <i class="ph-bold ph-check-circle text-xs"></i><span>Quyết Toán</span>
                            </button>
                        `}
                        <!-- 2. Xem -->
                        <button type="button" onclick="viewTripDetail('${escapeHtml(t.trip_code)}')" title="Xem chi tiết chuyến xe & chứng từ" 
                            class="h-7 px-2.5 text-[11px] font-bold text-teal-800 hover:text-teal-950 bg-teal-50 hover:bg-teal-100 rounded-lg transition-colors border border-teal-200 inline-flex items-center gap-1 cursor-pointer">
                            <i class="ph-bold ph-eye text-xs"></i><span>Xem</span>
                        </button>
                        <!-- 3. In -->
                        <button type="button" onclick="printCustomerSettlementVoucher(${t.id}, ${t.customer_id || 'null'})" title="In bảng kê đối soát công nợ khách hàng (SOA)" 
                            class="h-7 px-2.5 text-[11px] font-bold text-slate-700 hover:text-slate-950 bg-white hover:bg-slate-50 rounded-lg transition-colors border border-slate-200 shadow-2xs inline-flex items-center gap-1 cursor-pointer">
                            <i class="ph-bold ph-printer text-xs text-slate-500"></i><span>In</span>
                        </button>
                    </div>
                </td>
            </tr>
        `;
    }).join('');

    // Đồng bộ master checkbox thead
    const activeCheckboxes = document.querySelectorAll('.cust-settle-row-checkbox:not(:disabled)');
    const checkedCheckboxes = document.querySelectorAll('.cust-settle-row-checkbox:not(:disabled):checked');
    const masterCb = document.getElementById('cust-settle-select-all');
    if (masterCb) {
        masterCb.checked = activeCheckboxes.length > 0 && activeCheckboxes.length === checkedCheckboxes.length;
        masterCb.indeterminate = checkedCheckboxes.length > 0 && checkedCheckboxes.length < activeCheckboxes.length;
    }

    if (window.BimTableFooter && Array.isArray(displayList)) {
        const totalRev = displayList.reduce((sum, i) => sum + (Number(i.revenue) || 0), 0);
        const totalReimb = displayList.reduce((sum, i) => sum + (Number(i.reimbursable) || 0), 0);
        const totalRec = displayList.reduce((sum, i) => sum + (Number(i.total_receivable) || 0), 0);
        window.BimTableFooter.render('customer-settlements-table', {
            cells: [
                { html: '<span class="font-black text-slate-900 font-heading">TỔNG</span>', align: 'center', colspan: 2 },
                { html: `${displayList.length} chuyến`, colspan: 5 },
                { html: `<span class="text-teal-800 font-bold tabular-nums font-mono">${formatMoneyVND(totalRev)}</span>`, align: 'right' },
                { html: `<span class="text-amber-700 font-bold tabular-nums font-mono">${formatMoneyVND(totalReimb)}</span>`, align: 'right' },
                { html: `<span class="text-slate-900 font-black tabular-nums font-mono">${formatMoneyVND(totalRec)}</span>`, align: 'right' },
                { text: '', align: 'center', colspan: 3 }
            ]
        });
    }

    if (window.BimTableColumnManager && typeof window.BimTableColumnManager.register === 'function') {
        window.BimTableColumnManager.register('customer-settlements-table');
    }
}

function toggleSelectAllCustTrips(masterCheckbox) {
    const isChecked = masterCheckbox.checked;
    const visibleUnsettledTrips = (customerSettlementsCache || []).filter(t => !t.is_customer_settled);

    if (isChecked) {
        visibleUnsettledTrips.forEach(t => selectedCustTripIds.add(t.id));
    } else {
        visibleUnsettledTrips.forEach(t => selectedCustTripIds.delete(t.id));
    }

    document.querySelectorAll('.cust-settle-row-checkbox:not(:disabled)').forEach(cb => {
        cb.checked = isChecked;
    });

    updateCustBatchSettleButtonState();
}

function onCustSettleTripSelectionChange(tripId, isChecked) {
    if (typeof tripId !== 'undefined' && tripId !== null) {
        if (isChecked) {
            selectedCustTripIds.add(tripId);
        } else {
            selectedCustTripIds.delete(tripId);
        }
    } else {
        selectedCustTripIds.clear();
        document.querySelectorAll('.cust-settle-row-checkbox:checked').forEach(cb => {
            const id = parseInt(cb.getAttribute('data-trip-id'), 10);
            if (id) selectedCustTripIds.add(id);
        });
    }

    const activeCheckboxes = document.querySelectorAll('.cust-settle-row-checkbox:not(:disabled)');
    const checkedCheckboxes = document.querySelectorAll('.cust-settle-row-checkbox:not(:disabled):checked');
    const masterCb = document.getElementById('cust-settle-select-all');
    if (masterCb) {
        masterCb.checked = activeCheckboxes.length > 0 && activeCheckboxes.length === checkedCheckboxes.length;
        masterCb.indeterminate = checkedCheckboxes.length > 0 && checkedCheckboxes.length < activeCheckboxes.length;
    }

    updateCustBatchSettleButtonState();
}

function updateCustBatchSettleButtonState() {
    const btn = document.getElementById('btn-batch-settle-customer');
    const label = document.getElementById('btn-batch-settle-customer-label');
    if (!btn) return;

    const count = selectedCustTripIds.size;
    // Yêu cầu: Khi chọn nhiều chuyến (>= 2) thì nút hiển thị bên cạnh "Xem Bảng Kê SOA".
    // Trường hợp chỉ chọn 1 chuyến thì nút này ẩn, chỉ có nút trong từng dòng hiệu lực.
    if (count >= 2) {
        btn.classList.remove('hidden');
        btn.classList.add('inline-flex');
        if (label) label.innerText = `Quyết Toán Nhiều Chuyến (${count})`;
    } else {
        btn.classList.add('hidden');
        btn.classList.remove('inline-flex');
        if (label) label.innerText = 'Quyết Toán Nhiều Chuyến';
    }
}

function toggleAllCustomerSettleChecks(checked) {
    const masterCb = document.getElementById('cust-settle-select-all');
    if (masterCb) {
        masterCb.checked = checked;
        toggleSelectAllCustTrips(masterCb);
    }
}

async function toggleCustomerSettleSingle(tripId, action) {
    try {
        const res = await fetchWithAuth('/api/accounting/customer-reconciliation/', {
            method: 'POST',
            body: JSON.stringify({
                action: action,
                trip_ids: [tripId]
            })
        });
        const data = await res.json();
        if (!res.ok) throw new Error(data.message || data.error || 'Lỗi cập nhật quyết toán');
        showToast('success', data.message || 'Cập nhật quyết toán khách hàng thành công!', 'Thành Công');
        loadCustomerSettlementsData();
    } catch (err) {
        showToast('error', err.message || 'Lỗi thao tác quyết toán', 'Lỗi');
    }
}

function executeBatchCustomerSettlement() {
    // Lập Phiếu quyết toán khách hàng (bảng kê chỉ gồm cước & chi hộ, không có chi phí tài xế/đối tác)
    openSettlementStatement('CUSTOMER', Array.from(selectedCustTripIds), { with_cash: false });
}

function openSelectedCustomerSOAView() {
    const custId = document.getElementById('cust-settle-filter-customer')?.value;
    if (!custId) {
        const first = customerSettlementsCache[0];
        if (first && first.customer_id) {
            viewCustomerARStatement(first.customer_id);
            return;
        }
        showToast('warning', 'Vui lòng chọn một khách hàng để xem bảng kê đối soát SOA!', 'Chọn Khách Hàng');
        return;
    }
    viewCustomerARStatement(custId);
}

window.renderBookingOrderOptions = renderBookingOrderOptions;
window.filterBookingOrderOptions = filterBookingOrderOptions;
window.clearBookingOrderSearch = clearBookingOrderSearch;
window.lookupBookingPrice = lookupBookingPrice;
